window.ZHTS_PROTO_HTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,viewport-fit=cover\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n<meta name=\"apple-mobile-web-app-title\" content=\"中华通史\">\n<meta name=\"format-detection\" content=\"telephone=no\">\n<meta name=\"theme-color\" content=\"#f2f7fd\">\n<title>中华通史 · 五千年学习平台<\/title>\n<style>\n:root{\n  --bg:#f2f7fd;--surface:#fff;--surface2:#f7fbff;\n  --primary:#2563eb;--primary-deep:#1746b8;--accent:#5b8def;\n  --ink:#1e3350;--ink2:#4a6285;--ink3:#8399b6;\n  --line:#d9e6f7;--line2:#eaf2fc;\n  --ok:#159a55;--ok-bg:#e8f8ef;--no:#dc4c4c;--no-bg:#fdecee;\n  --gold:#e8a020;--shadow:0 10px 30px rgba(28,64,120,.10);--shadow-s:0 3px 14px rgba(28,64,120,.07);\n  --c1:#e3eefb;--c2:#d7e6f8;--c3:#cbe0f7;--c4:#bfd9f5;--c5:#b2d2f2;\n  --c6:#a6cbf0;--c7:#9ac4ee;--c8:#8ebdeb;--c9:#82b6e8;--c10:#76b0e5;\n  --r:18px;\n}\n*{box-sizing:border-box;margin:0;padding:0}\nhtml,body{height:100%;overflow:hidden}\nbody{\n  background:radial-gradient(1200px 600px at 15% -10%,#e2f0ff 0%,transparent 60%),radial-gradient(900px 500px at 100% 110%,#e6f2ff 0%,transparent 55%),var(--bg);\n  color:var(--ink);font:16px/1.7 \"PingFang SC\",\"Noto Sans SC\",\"Microsoft YaHei\",sans-serif;\n  -webkit-text-size-adjust:100%;-webkit-tap-highlight-color:transparent;\n}\nh1,h2,h3,h4{font-weight:700;line-height:1.35}\n.serif{font-family:\"Songti SC\",\"STSong\",\"Noto Serif SC\",serif}\nbutton,input,textarea{font:inherit;color:inherit}\nbutton{cursor:pointer;border:none;background:none;-webkit-user-select:none;user-select:none;touch-action:manipulation}\nbutton:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid rgba(37,99,235,.45);outline-offset:2px}\na{color:var(--primary);text-decoration:none}\n::-webkit-scrollbar{width:8px;height:8px}\n::-webkit-scrollbar-thumb{background:#c7dbf2;border-radius:8px}\n::-webkit-scrollbar-track{background:transparent}\n\n/* ===== 骨架 ===== */\n.shell{height:100vh;height:100dvh;display:flex;flex-direction:column;padding-top:env(safe-area-inset-top)}\n.topbar{flex:0 0 auto;height:66px;display:flex;align-items:center;gap:12px;padding:0 20px;background:rgba(255,255,255,.88);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px);border-bottom:1px solid var(--line);z-index:40;position:relative}\n.brand{display:flex;align-items:center;gap:9px;white-space:nowrap;flex:0 0 auto;cursor:pointer}\n.brand .seal{width:38px;height:38px;border-radius:11px;background:linear-gradient(145deg,#2563eb,#5b8def);color:#fff;display:grid;place-items:center;font-size:21px;box-shadow:0 4px 12px rgba(37,99,235,.28)}\n.brand b{font-size:19px;letter-spacing:1px;color:var(--primary-deep)}\n.brand small{display:block;font-size:10px;color:var(--ink3);letter-spacing:2px;line-height:1}\n.search-wrap{position:relative;flex:1 1 auto;max-width:420px;margin:0 auto}\n.search-wrap input{width:100%;height:44px;border:1px solid var(--line);background:var(--surface2);border-radius:999px;padding:0 16px 0 40px;font-size:14px;outline:none}\n.search-wrap input:focus{border-color:var(--primary);background:#fff;box-shadow:0 0 0 3px rgba(37,99,235,.10)}\n.search-wrap .si{position:absolute;left:15px;top:11px;font-size:16px;color:var(--ink3);pointer-events:none}\n.search-panel{position:absolute;top:52px;left:0;right:0;background:#fff;border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow);max-height:min(60vh,480px);overflow-y:auto;display:none;z-index:60;padding:6px}\n.search-panel.on{display:block}\n.search-panel button{display:block;width:100%;text-align:left;padding:11px 14px;border-radius:11px;font-size:13px;min-height:48px;border-bottom:1px solid var(--line2)}\n.search-panel button:last-child{border-bottom:none}\n.search-panel button b{color:var(--primary-deep);font-size:14px}\n.search-panel button small{color:var(--ink3);display:block;font-size:11px}\n.search-panel .none{padding:18px;color:var(--ink3);font-size:13px;text-align:center}\n.top-acts{display:flex;align-items:center;gap:6px;flex:0 0 auto}\n.chip{display:inline-flex;align-items:center;gap:7px;height:42px;padding:0 12px;border:1px solid var(--line);border-radius:999px;background:#fff;font-size:13px;color:var(--ink2);white-space:nowrap;min-height:42px}\n.chip:hover{border-color:var(--primary);color:var(--primary)}\n.chip.on{background:var(--primary);border-color:var(--primary);color:#fff}\n.chip .ring{width:22px;height:22px;transform:rotate(-90deg)}\n.chip .ring circle{fill:none;stroke-width:4}\n.icon-btn{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;font-size:18px;border:1px solid var(--line);background:#fff;min-height:42px}\n.icon-btn:hover{border-color:var(--primary)}\n.icon-btn.on{background:var(--primary);color:#fff;border-color:var(--primary)}\n#assistBtn{display:none}\n.grid{flex:1;min-height:0;display:grid;grid-template-columns:212px minmax(0,1fr) 272px}\n.sidebar{min-width:0;overflow-y:auto;border-right:1px solid var(--line);background:rgba(255,255,255,.55);padding:14px 12px 24px}\n.main{min-width:0;overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;padding:22px 26px 46px}\n.assist{min-width:0;overflow-y:auto;border-left:1px solid var(--line);background:rgba(255,255,255,.58);padding:18px 16px 30px}\n.drawer-mask{display:none;position:fixed;inset:66px 0 0;background:rgba(15,35,70,.34);z-index:44}\n.drawer-mask.on{display:block}\n.tabbar{display:none}\n\n.side-cap{font-size:11px;color:var(--ink3);letter-spacing:2px;padding:4px 10px 8px}\n.nav-item{display:flex;align-items:center;gap:11px;width:100%;height:46px;padding:0 12px;border-radius:12px;font-size:14px;color:var(--ink2);margin-bottom:3px;text-align:left;white-space:nowrap}\n.nav-item .ni{font-size:18px;width:22px;text-align:center;flex:0 0 auto}\n.nav-item:hover{background:rgba(37,99,235,.07)}\n.nav-item.on{background:var(--primary);color:#fff;font-weight:700;box-shadow:0 5px 14px rgba(37,99,235,.25)}\n.side-eras{margin-top:18px;border-top:1px dashed var(--line);padding-top:14px}\n.side-era{display:flex;align-items:center;gap:8px;width:100%;padding:7px 10px;border-radius:10px;font-size:12px;color:var(--ink2);text-align:left;min-height:38px}\n.side-era:hover{background:rgba(37,99,235,.08)}\n.side-era.on{background:rgba(37,99,235,.14);color:var(--primary-deep);font-weight:700}\n.side-era i{width:9px;height:9px;border-radius:50%;flex:0 0 auto;border:1px solid rgba(30,51,80,.12)}\n\n/* ===== 通用 ===== */\n.view{display:none}\n.view.on{display:block;animation:fade .28s ease}\n@keyframes fade{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--shadow-s)}\n.sec-title{display:flex;align-items:baseline;gap:10px;margin:22px 2px 12px}\n.sec-title h2{font-size:18px;color:var(--primary-deep)}\n.sec-title span{font-size:12px;color:var(--ink3)}\n.sec-title .more{margin-left:auto;font-size:13px;color:var(--primary);border:1px solid var(--line);background:#fff;border-radius:999px;padding:6px 14px;min-height:38px}\n.pill{display:inline-flex;align-items:center;gap:5px;border-radius:999px;padding:5px 12px;font-size:12px;background:rgba(37,99,235,.08);color:var(--primary-deep);white-space:nowrap}\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid var(--line);background:#fff;border-radius:12px;padding:9px 16px;font-size:14px;color:var(--ink2);min-height:44px}\n.btn:hover{border-color:var(--primary);color:var(--primary)}\n.btn.pri{background:var(--primary);border-color:var(--primary);color:#fff;font-weight:700;box-shadow:0 5px 14px rgba(37,99,235,.22)}\n.btn.pri:hover{background:var(--primary-deep);color:#fff}\n.btn.ghost{background:rgba(37,99,235,.06);border-color:transparent;color:var(--primary-deep)}\n.btn.on{background:var(--primary);color:#fff;border-color:var(--primary)}\n.btn.sm{min-height:38px;padding:6px 12px;font-size:12.5px;border-radius:10px}\n.btn:disabled{opacity:.45;cursor:default}\n.empty{text-align:center;color:var(--ink3);font-size:14px;padding:36px 16px;line-height:2}\n.hscroll{overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none}\n.hscroll::-webkit-scrollbar{display:none}\n\n/* ===== 首页 ===== */\n.hero{position:relative;overflow:hidden;border-radius:24px;padding:26px 28px;color:#fff;background:linear-gradient(118deg,#1c48ad 0%,#2f6fe6 52%,#78b0f2 100%);box-shadow:0 14px 34px rgba(31,80,180,.22);display:flex;align-items:center;gap:24px;min-height:178px}\n.hero:after{content:\"史\";position:absolute;right:26px;bottom:-56px;font:700 210px/1 \"Songti SC\",\"STSong\",serif;color:rgba(255,255,255,.10);pointer-events:none}\n.hero .hero-txt{flex:1;min-width:0;position:relative;z-index:1}\n.hero h1{font-size:29px;letter-spacing:2px;margin-bottom:6px}\n.hero p{font-size:13.5px;color:rgba(255,255,255,.88);line-height:1.8}\n.hero .hero-btns{display:flex;gap:9px;margin-top:16px;flex-wrap:wrap;position:relative;z-index:1}\n.hero .btn{background:rgba(255,255,255,.16);border-color:rgba(255,255,255,.42);color:#fff}\n.hero .btn.pri{background:#fff;color:var(--primary-deep);border-color:#fff;font-weight:700}\n.hero-ring{position:relative;z-index:1;flex:0 0 auto;width:132px;height:132px;display:grid;place-items:center;text-align:center}\n.hero-ring svg{position:absolute;inset:0;transform:rotate(-90deg)}\n.hero-ring b{font-size:27px;line-height:1}\n.hero-ring small{display:block;font-size:11px;color:rgba(255,255,255,.85);margin-top:4px}\n.stat-row{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:14px}\n.stat{display:flex;align-items:center;gap:12px;padding:14px 16px}\n.stat .ico{width:42px;height:42px;border-radius:13px;background:var(--surface2);display:grid;place-items:center;font-size:21px}\n.stat b{font-size:21px;color:var(--primary-deep);line-height:1.1}\n.stat span{font-size:11.5px;color:var(--ink3);display:block}\n.era-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}\n.era-tile{position:relative;border-radius:16px;border:1px solid rgba(37,99,235,.14);padding:13px 9px 12px;text-align:center;min-height:126px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;overflow:hidden;transition:transform .16s,box-shadow .16s}\n.era-tile:hover{transform:translateY(-4px);box-shadow:var(--shadow)}\n.era-tile .no{position:absolute;top:6px;left:9px;font-size:10px;color:rgba(30,51,80,.42);font-weight:700}\n.era-tile .ico{font-size:29px;line-height:1.2}\n.era-tile b{font-size:14px;color:#173863}\n.era-tile small{font-size:10px;color:#5b7395;line-height:1.35}\n.era-tile .bar{position:absolute;bottom:0;left:0;height:4px;width:100%;background:rgba(37,99,235,.16)}\n.era-tile .bar i{display:block;height:100%;background:var(--primary)}\n.two-col{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}\n.pad{padding:18px 20px}\n.mini-h{font-size:15px;color:var(--primary-deep);margin-bottom:10px;display:flex;align-items:center;gap:7px}\n.daily-q{font-size:15px;line-height:1.75;margin-bottom:12px}\n.opt-mini{display:block;width:100%;text-align:left;border:1px solid var(--line);border-radius:11px;padding:9px 13px;margin-bottom:7px;font-size:13.5px;min-height:42px;background:var(--surface2)}\n.opt-mini:hover{border-color:var(--primary)}\n.opt-mini.right{background:var(--ok-bg);border-color:var(--ok);color:var(--ok)}\n.opt-mini.wrong{background:var(--no-bg);border-color:var(--no);color:var(--no)}\n.badges{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}\n.badge{text-align:center;border-radius:14px;padding:12px 6px;border:1px dashed var(--line);background:var(--surface2);opacity:.5}\n.badge.got{opacity:1;border-style:solid;background:#fff;box-shadow:var(--shadow-s)}\n.badge .bi{font-size:26px;line-height:1.3}\n.badge b{display:block;font-size:12px;color:var(--primary-deep)}\n.badge small{font-size:10px;color:var(--ink3);line-height:1.4;display:block}\n\n/* ===== 时间轴 ===== */\n.tl-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch;padding:18px 6px 24px;scrollbar-width:thin}\n.tl-track{display:flex;min-width:max-content;position:relative;padding-top:8px}\n.tl-track:before{content:\"\";position:absolute;left:0;right:0;top:88px;height:5px;border-radius:5px;background:linear-gradient(90deg,var(--c1),var(--c10))}\n.tl-era{flex:0 0 196px;width:196px;padding:0 8px;position:relative;cursor:pointer}\n.tl-head{border-radius:14px;padding:10px 8px;text-align:center;border:1px solid rgba(37,99,235,.16);min-height:74px}\n.tl-era.on .tl-head{box-shadow:0 0 0 3px var(--primary);border-color:var(--primary)}\n.tl-head b{display:block;font-size:15px;color:#173863}\n.tl-head small{font-size:10.5px;color:#5b7395}\n.tl-dot{position:absolute;top:80px;left:50%;transform:translateX(-50%);width:17px;height:17px;border-radius:50%;background:#fff;border:4px solid var(--primary);z-index:2}\n.tl-nodes{margin-top:26px;display:flex;flex-direction:column;gap:8px}\n.tl-node{border-radius:12px;background:#fff;border:1px solid var(--line);padding:9px 11px;text-align:left;font-size:12.5px;min-height:46px;box-shadow:var(--shadow-s)}\n.tl-node:hover{border-color:var(--primary)}\n.tl-node b{display:block;color:var(--primary-deep);font-size:13px}\n.tl-node small{color:var(--ink3);font-size:10.5px}\n.tl-node.done:after{content:\"✓\";float:right;color:var(--ok);font-weight:700}\n.tl-preview{margin-top:6px;display:grid;grid-template-columns:190px 1fr;gap:16px;padding:18px 20px;align-items:center}\n.tl-preview img{width:100%;height:112px;object-fit:cover;border-radius:12px;background:var(--surface2)}\n.tl-preview h3{font-size:19px;color:var(--primary-deep);margin-bottom:4px}\n.tl-preview p{font-size:13.5px;color:var(--ink2);line-height:1.75}\n\n/* ===== 研读 ===== */\n.study-head{display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding:2px 0 14px}\n.study-head .sh-txt{flex:1;min-width:220px}\n.study-head h2{font-size:26px;color:var(--primary-deep);display:flex;align-items:center;gap:9px;flex-wrap:wrap}\n.study-head .yr{font-size:12px;color:#fff;background:var(--accent);border-radius:999px;padding:4px 12px;font-weight:400}\n.study-head p{font-size:13px;color:var(--ink2);margin-top:3px}\n.study-nav{display:flex;gap:7px}\n.node-pills{display:flex;gap:8px;overflow-x:auto;padding:2px 2px 12px;scrollbar-width:none}\n.node-pills::-webkit-scrollbar{display:none}\n.node-pill{flex:0 0 auto;border:1px solid var(--line);background:#fff;border-radius:999px;padding:8px 15px;font-size:13px;min-height:42px;white-space:nowrap}\n.node-pill.on{background:var(--primary);color:#fff;border-color:var(--primary);font-weight:700}\n.node-pill .tick{color:var(--ok);margin-left:4px}\n.node-pill.on .tick{color:#fff}\n.study-top{display:grid;grid-template-columns:minmax(220px,.85fr) 1.15fr;gap:14px}\n.scene{position:relative;border-radius:16px;overflow:hidden;background:linear-gradient(140deg,var(--c2),var(--c5));min-height:186px;border:1px solid var(--line)}\n.scene img{width:100%;height:100%;min-height:186px;max-height:230px;object-fit:cover;display:block}\n.scene .cap{position:absolute;left:0;right:0;bottom:0;padding:8px 12px;background:linear-gradient(transparent,rgba(15,35,70,.6));color:#fff;font-size:12px}\n.scene .ph{display:none}\n.scene.noimg{display:grid;place-items:center;text-align:center;color:var(--ink2);font-size:13px;padding:20px}\n.scene.noimg .ph{display:block;line-height:1.8}\n.scene.noimg .big{font-size:44px;display:block}\n.scene.noimg img,.scene.noimg .cap{display:none}\n.quick{padding:16px 18px}\n.quick-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}\n.qi{background:var(--surface2);border-radius:12px;padding:10px 12px;border:1px solid var(--line2)}\n.qi b{display:block;font-size:11px;color:var(--ink3);margin-bottom:3px}\n.qi span{font-size:13px;line-height:1.55;color:var(--ink)}\n.study-acts{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}\n.dim-box{margin-top:14px;padding:0;overflow:hidden}\n.dim-tabs{display:flex;gap:6px;overflow-x:auto;padding:12px 14px;border-bottom:1px solid var(--line);scrollbar-width:none}\n.dim-tabs::-webkit-scrollbar{display:none}\n.dim-tab{flex:0 0 auto;border-radius:999px;border:1px solid var(--line);background:var(--surface2);padding:8px 14px;font-size:13px;min-height:42px;white-space:nowrap}\n.dim-tab.on{background:var(--primary);color:#fff;border-color:var(--primary);font-weight:700}\n.dim-body{padding:20px 24px 22px;min-height:180px}\n.dim-body h4{font-size:15px;color:var(--primary-deep);margin-bottom:10px;display:flex;align-items:center;gap:8px}\n.dim-body p{font-size:15.5px;line-height:1.95;color:#263c5c;letter-spacing:.2px}\n.dim-body .src{margin-top:14px;padding-top:12px;border-top:1px dashed var(--line);font-size:11.5px;color:var(--ink3)}\n.mem-cover{position:relative}\n.mem-cover.locked{cursor:pointer}\n.mem-cover.locked .dim-body{position:relative}\n.mem-cover.locked .dim-body p{filter:blur(7px);opacity:.6;transition:filter .25s}\n.mem-cover.locked .dim-body:after{content:\"👆 记忆模式 · 点击卡片揭开答案\";position:absolute;left:0;right:0;bottom:0;display:block;text-align:center;font-size:13px;color:var(--primary);padding:10px;background:linear-gradient(transparent,#fff 45%)}\n.study-foot{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:16px}\n.study-foot .sp{flex:1}\n.note-editor{margin-top:14px;padding:16px 18px;display:none}\n.note-editor.on{display:block}\n.note-editor textarea{width:100%;min-height:96px;border:1px solid var(--line);border-radius:12px;padding:12px;font-size:14.5px;line-height:1.7;resize:vertical;background:var(--surface2)}\n\n/* ===== 对照 ===== */\n.cmp-card{padding:18px 20px;margin-bottom:14px}\n.cmp-card h3{font-size:16px;color:var(--primary-deep);margin-bottom:12px;display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n.cmp-card h3 small{font-size:12px;color:var(--accent);font-weight:400}\n.cmp-cols{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.cmp-col{border-radius:13px;padding:13px 15px;font-size:13.5px;line-height:1.85;color:#2b4368;background:var(--surface2);border-left:4px solid var(--primary)}\n.cmp-col.world{background:#f6f9ff;border-left-color:var(--accent)}\n.cmp-col b{display:block;font-size:12px;color:var(--primary-deep);margin-bottom:5px}\n\n/* ===== 测验 ===== */\n.lv-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}\n.lv{border-radius:16px;padding:15px 14px;text-align:left;border:1px solid rgba(37,99,235,.15);min-height:118px;position:relative;overflow:hidden;transition:transform .16s}\n.lv:hover{transform:translateY(-3px);box-shadow:var(--shadow)}\n.lv .n{font-size:10px;color:rgba(30,51,80,.55);letter-spacing:1px}\n.lv b{display:block;font-size:15px;color:#173863;margin:3px 0 6px}\n.lv .stars{font-size:14px;color:var(--gold);letter-spacing:2px}\n.lv .best{font-size:11px;color:#5b7395;display:block;margin-top:4px}\n.lv.done:after{content:\"✓\";position:absolute;right:12px;top:10px;color:var(--ok);font-weight:700;font-size:17px}\n.q-wrap{max-width:760px;margin:0 auto}\n.q-head{display:flex;align-items:center;gap:12px;margin-bottom:14px}\n.q-head .prog{flex:1;height:9px;border-radius:9px;background:var(--line2);overflow:hidden}\n.q-head .prog i{display:block;height:100%;background:linear-gradient(90deg,var(--primary),var(--accent));border-radius:9px;transition:width .3s}\n.q-head span{font-size:12px;color:var(--ink3);white-space:nowrap}\n.q-card{padding:24px 26px}\n.q-card .tag{font-size:11px;color:var(--accent);letter-spacing:1px}\n.q-card h3{font-size:20px;line-height:1.7;margin:8px 0 18px;color:var(--ink)}\n.q-opts{display:grid;gap:10px}\n.q-opt{display:flex;align-items:center;gap:12px;width:100%;text-align:left;border:1.5px solid var(--line);background:var(--surface2);border-radius:14px;padding:13px 16px;font-size:15px;min-height:56px;line-height:1.6}\n.q-opt:hover{border-color:var(--primary)}\n.q-opt .k{width:28px;height:28px;flex:0 0 auto;border-radius:9px;background:#fff;border:1px solid var(--line);display:grid;place-items:center;font-size:13px;font-weight:700;color:var(--ink2)}\n.q-opt.right{background:var(--ok-bg);border-color:var(--ok);color:#0f6b3c}\n.q-opt.wrong{background:var(--no-bg);border-color:var(--no);color:#a83232}\n.q-opt.right .k,.q-opt.wrong .k{border:none;color:#fff}\n.q-opt.right .k{background:var(--ok)}\n.q-opt.wrong .k{background:var(--no)}\n.q-opt.disabled{pointer-events:none;opacity:.72}\n.q-opt.right,.q-opt.wrong{opacity:1}\n.q-explain{margin-top:14px;border-radius:13px;padding:13px 16px;font-size:13.5px;line-height:1.8;background:var(--surface2);border-left:4px solid var(--primary)}\n.q-explain b{color:var(--primary-deep)}\n.q-foot{display:flex;justify-content:flex-end;margin-top:14px;gap:8px}\n.result{text-align:center;padding:34px 24px}\n.result .big{font-size:64px;line-height:1}\n.result h3{font-size:24px;color:var(--primary-deep);margin:10px 0 4px}\n.result .stars{font-size:30px;color:var(--gold);letter-spacing:6px;margin:8px 0}\n.result p{font-size:14px;color:var(--ink2);line-height:1.9}\n.result .btns{display:flex;gap:10px;justify-content:center;margin-top:20px;flex-wrap:wrap}\n\n/* ===== 闪卡 ===== */\n.flip-stage{max-width:620px;margin:10px auto 0}\n.flip{perspective:1400px;height:320px;cursor:pointer}\n.flip-in{position:relative;width:100%;height:100%;transform-style:preserve-3d;-webkit-transform-style:preserve-3d;transition:transform .55s cubic-bezier(.3,.8,.3,1)}\n.flip.on .flip-in{transform:rotateY(180deg)}\n.face{position:absolute;inset:0;-webkit-backface-visibility:hidden;backface-visibility:hidden;border-radius:22px;padding:26px 30px;display:flex;flex-direction:column;justify-content:center;box-shadow:var(--shadow);border:1px solid var(--line)}\n.face.front{background:linear-gradient(140deg,#fff,#eaf3ff);align-items:center;text-align:center}\n.face.back{background:linear-gradient(140deg,#2256c9,#5b8def);color:#fff;transform:rotateY(180deg)}\n.face .lbl{font-size:12px;letter-spacing:3px;color:var(--accent)}\n.face.front h3{font-size:30px;color:var(--primary-deep);margin:14px 0 10px}\n.face.front p{font-size:14px;color:var(--ink2)}\n.face.front .hint{margin-top:24px;font-size:12px;color:var(--ink3)}\n.face.back h3{font-size:23px;margin-bottom:10px}\n.face.back p{font-size:14px;line-height:1.9;color:rgba(255,255,255,.94)}\n.face.back .tags{margin-top:14px;display:flex;gap:7px;flex-wrap:wrap}\n.face.back .tags span{background:rgba(255,255,255,.18);border-radius:999px;padding:4px 11px;font-size:11.5px}\n.flip-ctrl{display:flex;justify-content:center;gap:10px;margin-top:18px;flex-wrap:wrap}\n\n/* ===== 笔记 / 报告 ===== */\n.note-item{padding:15px 18px;margin-bottom:11px}\n.note-item h4{font-size:15px;color:var(--primary-deep);display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n.note-item p{font-size:14px;line-height:1.8;margin-top:6px;white-space:pre-wrap;color:#2b4368}\n.note-item .row{display:flex;gap:8px;margin-top:10px;flex-wrap:wrap}\n.bar-row{display:flex;align-items:center;gap:12px;padding:11px 2px;border-bottom:1px dashed var(--line2)}\n.bar-row .nm{width:112px;flex:0 0 auto;font-size:13px}\n.bar-row .bar{flex:1;height:10px;background:var(--line2);border-radius:9px;overflow:hidden}\n.bar-row .bar i{display:block;height:100%;background:linear-gradient(90deg,var(--c5),var(--primary));border-radius:9px}\n.bar-row .pc{width:56px;text-align:right;font-size:12px;color:var(--ink3)}\n.report-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n.day-strip{display:flex;gap:6px;margin-top:12px}\n.day-strip i{flex:1;height:34px;border-radius:8px;background:var(--line2);display:grid;place-items:center;font-size:10px;color:var(--ink3);font-style:normal}\n.day-strip i.on{background:var(--primary);color:#fff}\n\n/* ===== 右栏 ===== */\n.as-title{font-size:11px;letter-spacing:2px;color:var(--ink3);margin:2px 2px 10px}\n.as-card{padding:15px 16px;margin-bottom:12px}\n.as-ring{display:flex;align-items:center;gap:14px}\n.as-ring svg{transform:rotate(-90deg);flex:0 0 auto}\n.as-ring b{font-size:19px;color:var(--primary-deep);line-height:1.2}\n.as-ring small{font-size:11px;color:var(--ink3);display:block}\n.as-kv{display:flex;gap:9px;font-size:12.5px;line-height:1.7;padding:7px 0;border-bottom:1px dashed var(--line2)}\n.as-kv:last-child{border:none}\n.as-kv b{flex:0 0 44px;color:var(--ink3);font-weight:400}\n.as-kv span{flex:1;color:#2b4368}\n.as-tip{font-size:13px;line-height:1.8;color:#2b4368}\n.as-badges{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}\n.as-badges span{font-size:20px;filter:grayscale(1);opacity:.35}\n.as-badges span.on{filter:none;opacity:1}\n\n/* ===== Toast ===== */\n#toast{position:fixed;left:50%;bottom:calc(34px + env(safe-area-inset-bottom));transform:translate(-50%,18px);background:rgba(20,45,90,.94);color:#eaf2fc;padding:12px 22px;border-radius:999px;font-size:13.5px;z-index:120;opacity:0;pointer-events:none;transition:.3s;max-width:86vw;text-align:center;line-height:1.6}\n#toast.on{opacity:1;transform:translate(-50%,0)}\n\n/* ===== 响应式：iPad 横屏 1024~1180 ===== */\n@media (max-width:1240px){\n  .grid{grid-template-columns:78px minmax(0,1fr) 242px}\n  .sidebar{padding:14px 8px}\n  .nav-item{justify-content:center;padding:0;font-size:0;gap:0}\n  .nav-item .ni{font-size:21px;width:auto}\n  .side-cap,.side-eras{display:none}\n  .main{padding:20px 20px 42px}\n  .assist{padding:16px 12px}\n}\n/* ===== iPad 竖屏 768~834：右栏改抽屉 ===== */\n@media (max-width:1000px){\n  .grid{grid-template-columns:78px minmax(0,1fr)}\n  .assist{position:fixed;right:0;top:66px;bottom:0;width:min(310px,86vw);z-index:46;transform:translateX(105%);transition:transform .3s;box-shadow:-12px 0 34px rgba(20,50,100,.16);background:#fff;padding-bottom:env(safe-area-inset-bottom)}\n  .assist.open{transform:none}\n  #assistBtn{display:grid}\n  .era-grid{grid-template-columns:repeat(5,1fr)}\n}\n/* ===== 手机 / 窄分屏 ===== */\n@media (max-width:700px){\n  .topbar{height:58px;padding:0 12px;gap:8px}\n  .brand b{font-size:16px}\n  .brand small,.brand .seal{display:none}\n  .chip .txt{display:none}\n  .chip{padding:0 9px}\n  #memBtn{display:none}\n  .grid{display:block}\n  .sidebar{display:none}\n  .main{height:100%;padding:16px 14px calc(96px + env(safe-area-inset-bottom))}\n  .drawer-mask{inset:58px 0 0}\n  .assist{top:58px}\n  .tabbar{display:flex;position:fixed;left:0;right:0;bottom:0;height:calc(64px + env(safe-area-inset-bottom));padding-bottom:env(safe-area-inset-bottom);background:rgba(255,255,255,.95);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);border-top:1px solid var(--line);z-index:42;overflow-x:auto;scrollbar-width:none}\n  .tabbar::-webkit-scrollbar{display:none}\n  .tabbar button{flex:1 0 62px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;font-size:10px;color:var(--ink3);min-height:44px}\n  .tabbar button .ni{font-size:19px}\n  .tabbar button.on{color:var(--primary);font-weight:700}\n  .hero{padding:20px;min-height:auto;flex-direction:column;align-items:flex-start;gap:10px}\n  .hero h1{font-size:23px}\n  .hero-ring{position:absolute;right:14px;top:12px;width:92px;height:92px}\n  .hero-ring b{font-size:19px}\n  .stat-row{grid-template-columns:repeat(3,1fr);gap:8px}\n  .stat{padding:10px;gap:7px}\n  .stat .ico{width:32px;height:32px;font-size:17px}\n  .stat b{font-size:17px}\n  .era-grid{grid-template-columns:repeat(2,1fr)}\n  .two-col,.report-grid,.quick-grid,.cmp-cols,.study-top,.tl-preview,.lv-grid,.badges{grid-template-columns:1fr}\n  .lv-grid{grid-template-columns:repeat(2,1fr)}\n  .badges{grid-template-columns:repeat(4,1fr)}\n  .study-head h2{font-size:22px}\n  .dim-body{padding:16px}\n  .dim-body p{font-size:15px}\n  .q-card{padding:18px}\n  .q-card h3{font-size:17px}\n  .scene img{min-height:150px}\n  .tl-preview img{display:none}\n}\n@media (hover:hover){\n  .btn:hover{box-shadow:var(--shadow-s)}\n}\n@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}\n@media print{\n  body{overflow:visible;background:#fff}.shell{height:auto}.topbar,.sidebar,.assist,.tabbar,#toast,.search-panel{display:none!important}\n  .grid{display:block}.main{overflow:visible;height:auto;padding:0}.view{display:none!important}.view.on{display:block!important}\n}\n<\/style>\n<\/head>\n<body>\n<div class=\"shell\">\n  <header class=\"topbar\">\n    <div class=\"brand\" data-act=\"nav\" data-v=\"home\" role=\"button\" tabindex=\"0\" aria-label=\"回到首页\">\n      <span class=\"seal\">史<\/span>\n      <span><b class=\"serif\">中华通史<\/b><small>FIVE THOUSAND YEARS<\/small><\/span>\n    <\/div>\n    <div class=\"search-wrap\">\n      <span class=\"si\">🔍<\/span>\n      <input id=\"searchInput\" type=\"search\" autocomplete=\"off\" placeholder=\"搜索事件、人物、朝代、关键词…\" aria-label=\"搜索历史知识\">\n      <div class=\"search-panel\" id=\"searchPanel\"><\/div>\n    <\/div>\n    <div class=\"top-acts\">\n      <button class=\"chip\" id=\"progressChip\" data-act=\"nav\" data-v=\"progress\" title=\"学习报告\"><svg class=\"ring\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\" stroke=\"#dbe7f7\"><\/circle><circle id=\"ringArc\" cx=\"12\" cy=\"12\" r=\"9\" stroke=\"#2563eb\" stroke-linecap=\"round\"><\/circle><\/svg><span class=\"txt\" id=\"progressTxt\">0 / 17<\/span><\/button>\n      <button class=\"icon-btn\" id=\"memBtn\" data-act=\"mem\" title=\"记忆模式\">🔖<\/button>\n      <button class=\"icon-btn\" data-act=\"tip\" title=\"历史小贴士\">💡<\/button>\n      <button class=\"icon-btn\" id=\"assistBtn\" data-act=\"assist\" title=\"学习助手\">📋<\/button>\n    <\/div>\n  <\/header>\n\n  <div class=\"grid\">\n    <aside class=\"sidebar\">\n      <div class=\"side-cap\">学习导航<\/div>\n      <div id=\"sideNav\"><\/div>\n      <div class=\"side-eras\" id=\"sideEras\"><\/div>\n    <\/aside>\n\n    <main class=\"main\" id=\"main\">\n      <section class=\"view on\" id=\"v-home\"><\/section>\n      <section class=\"view\" id=\"v-timeline\"><\/section>\n      <section class=\"view\" id=\"v-study\"><\/section>\n      <section class=\"view\" id=\"v-compare\"><\/section>\n      <section class=\"view\" id=\"v-quiz\"><\/section>\n      <section class=\"view\" id=\"v-cards\"><\/section>\n      <section class=\"view\" id=\"v-notes\"><\/section>\n      <section class=\"view\" id=\"v-progress\"><\/section>\n    <\/main>\n\n    <aside class=\"assist\" id=\"assist\"><\/aside>\n  <\/div>\n  <div class=\"drawer-mask\" id=\"drawerMask\" data-act=\"closeAssist\"><\/div>\n  <nav class=\"tabbar\" id=\"tabbar\"><\/nav>\n<\/div>\n<div id=\"toast\"><\/div>\n\n<script>\nconst ERAS = [\n  {name:\"史前文明\", color:\"var(--c1)\", desc:\"文明曙光，满天星斗\", ico:\"🦣\"},\n  {name:\"先秦\",     color:\"var(--c2)\", desc:\"从王朝初创到大变革，制度与思想的奠基期\", ico:\"🏺\"},\n  {name:\"秦汉\",     color:\"var(--c3)\", desc:\"大一统帝国的确立与成熟\", ico:\"⚔️\"},\n  {name:\"魏晋南北朝\",color:\"var(--c4)\", desc:\"分裂与融合，盛世的孕育\", ico:\"🐎\"},\n  {name:\"隋唐\",     color:\"var(--c5)\", desc:\"帝国再造与黄金时代\", ico:\"🏯\"},\n  {name:\"辽宋夏金\", color:\"var(--c6)\", desc:\"多政权并立下的经济文化巅峰\", ico:\"🖌\"},\n  {name:\"元明清\",   color:\"var(--c7)\", desc:\"空前大一统与帝制定型\", ico:\"🐉\"},\n  {name:\"晚清\",     color:\"var(--c8)\", desc:\"三千年未有之大变局\", ico:\"🚢\"},\n  {name:\"民国\",     color:\"var(--c9)\", desc:\"从帝制到共和的转型\", ico:\"🏛\"},\n  {name:\"新中国\",   color:\"var(--c10)\",desc:\"站起来、富起来、强起来\", ico:\"🚀\"}\n];\nconst DIMS = [\n  {key:\"dimension_politics\", label:\"🏛 政治制度\"},\n  {key:\"dimension_economy\", label:\"💰 经济发展\"},\n  {key:\"dimension_nation\", label:\"🗺 民族与疆域\"},\n  {key:\"dimension_culture\", label:\"📖 思想文化教育\"},\n  {key:\"dimension_science\", label:\"🔬 科技与社会生活\"},\n  {key:\"dimension_summary\", label:\"⭐ 时代总评\"}\n];\nconst NODES = [\n{id:1,era:\"史前文明\",node_title:\"中华文明起源\",year_start:\"约前170万年\",year_end:\"约前2070\",year_label:\"约170万年前 — 约公元前2070年\",is_anchor_point:true,\n dimension_politics:\"社会组织经历了原始群→母系氏族公社→父系氏族公社→部落联盟的演变。母系氏族以女性血缘为纽带（如半坡、河姆渡），父系氏族出现贫富分化与权贵墓葬（如良渚、陶寺）。传说中的尧、舜、禹实行禅让制，首领由推举产生；大禹治水十三年三过家门而不入，因功赢得威望。此时还没有国家、军队和法律，主要靠氏族习惯和首领威望维持秩序。\",\n dimension_economy:\"旧石器时代使用打制石器，靠采集和渔猎为生；距今约一万年起进入新石器时代，出现磨制石器和原始农业，形成南稻北粟两大农业起源中心。河姆渡居民（距今约7000年）种植水稻、住干栏式房屋、饲养家猪；半坡居民（距今约6000年）种植粟、住半地穴式房屋、烧制彩陶。手工业方面制陶、纺织、酿酒相继出现，晚期手工业已与农业分工，良渚社会能组织大规模的筑城与水利工程。\",\n dimension_nation:\"中华大地上活跃着华夏、东夷、苗蛮等史前族群集团。相传炎帝部落与黄帝部落结成联盟，在涿鹿之战中打败蚩尤，此后两个部落逐渐融合，炎黄部落在不断交往交流中融入周边族群，形成了后来华夏族的主干。炎黄因此被尊为人文始祖，海内外华人自称炎黄子孙。\",\n dimension_culture:\"文字产生之前，先民已在使用刻画符号记事：河南舞阳贾湖的龟甲刻符、山东大汶口的陶文、山西陶寺的朱书陶壶，都被视为汉字的萌芽。仰韶文化的彩陶、红山文化和良渚文化的精美玉器（如玉琮、玉璧）展现了高度发达的审美与礼仪观念。自然崇拜、图腾崇拜和祖先崇拜是原始宗教的主要形式，祭祀活动由氏族首领主持，成为后世礼制的源头。\",\n dimension_science:\"人工取火（钻木取火）的掌握极大改变了生活；弓箭、耒耜（翻土农具）普遍使用。山西陶寺遗址的古观象台距今约4100年，可通过观测日出方位确定节气，说明天文历法知识已经萌芽。先民还掌握了养蚕缫丝（西阴村出土半枚蚕茧）、麻纺织和酿酒技术，医学处于以草药经验积累为主的阶段。\",\n dimension_summary:\"中华文明的孕育期。考古学揭示各区域文化如满天星斗般多元起源——黄河流域的仰韶与龙山、长江流域的河姆渡与良渚、辽河流域的红山——又在长期交流中走向一体，为王朝国家的诞生奠定了经济、文化与政治基础。\",\n world:\"距今约5000年前后，两河流域苏美尔城邦发明楔形文字并建造城市，古埃及在约公元前3100年实现统一并留下金字塔，印度河流域出现哈拉帕文明，欧洲克里特岛兴起米诺斯文明。人类各大文明几乎同时迈入早期文明的门槛。\",\n key_event_tags:\"元谋人｜河姆渡｜半坡｜良渚｜禅让\",figures:\"炎帝 · 黄帝 · 尧 · 舜 · 禹\",cause:\"冰期结束、气候转暖，农业起源\",effect:\"夏朝建立，中国进入王朝时代\",source_note:\"考古学文化与《史记·五帝本纪》等传说文献互证\"},\n{id:2,era:\"先秦\",node_title:\"夏 · 商 · 西周\",year_start:\"约前2070\",year_end:\"前771\",year_label:\"约公元前2070 — 公元前771年\",is_anchor_point:true,\n dimension_politics:\"约公元前2070年禹建立夏朝，其子启继位，世袭制取代禅让制，王位传子不传贤，家天下开启。商朝实行内外服制：商王直接控制王畿，外服方国名义臣服；商王通过占卜（贞人集团）垄断神权来强化王权。西周确立分封制（封建亲戚，以藩屏周，分封同姓亲族与功臣共七十一国）、宗法制（以嫡长子继承制为核心）和礼乐制度（天子用九鼎八簋、诸侯七鼎的等级规格），三者互为表里，形成家国同构的政治框架。\",\n dimension_economy:\"青铜铸造进入鼎盛期，但青铜农具极少，农业生产仍以木、石、骨、蚌器为主，实行井田制——土地名义上归周王所有，庶人在田间集体耕作，公田收成归贵族。手工业由官府垄断（工商食官）。商代以海贝为货币，出现最早的货币形态之一；城市（如殷墟）已具备相当规模。\",\n dimension_nation:\"商朝北伐鬼方、东征人方，控制范围达长江流域；西周通过大规模分封，将周人、殷遗民和当地族群整合于封国之内，燕、齐、鲁、卫、宋、晋、吴等国的建立推动中原文化与四方族群深度融合。普天之下，莫非王土的观念形成，中国、天下等政治地理概念开始出现。\",\n dimension_culture:\"商代甲骨文是成熟汉字体系，单字四千以上，1899年由王懿荣首先识别，殷墟历年出土甲骨约15万片，记录了祭祀、战争、田猎、疾病等丰富内容。西周金文（青铜铭文）延续，毛公鼎铭文近500字为传世最长。礼乐制度规定了不同等级的礼器、音乐规格，《诗经》中的雅、颂即庙堂乐歌。敬天保民、明德慎罚的思想萌芽，成为儒家民本思想的先声。\",\n dimension_science:\"青铜冶铸登峰造极：司母戊鼎（后母戊鼎）重832.84公斤，为现存最重的商代青铜器；四羊方尊以分铸法铸成，工艺精湛。商代已使用干支纪日法，甲骨文中有日食、月食和新星记录。西周历法渐趋完善，设立专官观测天象。《周易》的形成反映了阴阳辩证思维的早期形态。\",\n dimension_summary:\"中华政治文明的奠基期。世袭制、分封制、宗法制与礼乐制度共同塑造了此后近三千年的政治底色：以血缘为纽带的等级秩序、家国同构的治理模式，都从这一时期发端。西周末年王权衰落、礼崩乐坏，孕育着大变革。\",\n world:\"同期，古埃及新王国时期（拉美西斯二世时代）国力鼎盛；两河流域古巴比伦王国颁布《汉谟拉比法典》（约公元前1754年），是现存最早的较完整成文法典之一；欧洲处于迈锡尼文明与荷马时代；腓尼基人发明字母文字并广泛传播。\",\n key_event_tags:\"世袭制｜分封制｜宗法制｜甲骨文｜礼乐\",figures:\"商汤 · 周文王 · 周武王 · 周公\",cause:\"史前文明积累与青铜技术突破\",effect:\"礼乐秩序崩解，进入春秋争霸\",source_note:\"殷墟甲骨、《诗经》《尚书》及金文材料\"},\n{id:3,era:\"先秦\",node_title:\"春秋战国（东周）\",year_start:\"前770\",year_end:\"前221\",year_label:\"公元前770 — 公元前221年\",is_anchor_point:true,\n dimension_politics:\"公元前770年平王东迁洛邑，王室东移后权威衰落，进入春秋（前770—前476）与战国（前475—前221）。春秋五霸（齐桓公、晋文公等）打着尊王攘夷旗号争霸；战国七雄间兼并战争激烈。各国竞相变法：李悝在魏国、吴起在楚国变法，商鞅在秦先后两次变法（前356、前350），内容有废井田开阡陌、奖励耕战、按军功授爵、建立县制等，秦国由此崛起。世卿世禄制被官僚任免制取代，郡县制在边地和新获领土萌芽，官僚政治的雏形出现。\",\n dimension_economy:\"春秋后期铁农具和牛耕出现并逐步推广，生产力飞跃使井田之外大量私田被开垦；鲁国初税亩（前594）承认土地私有的合法性，井田制逐步瓦解。水利工程成就斐然：都江堰（约前256年，李冰父子主持）使成都平原成为天府之国，郑国渠使关中成沃野。商业随之繁荣，临淄、邯郸、陶等成为商业都会，铜铸布币、刀币流通各国，出现范蠡（陶朱公）、白圭等著名商人。\",\n dimension_nation:\"在尊王攘夷的旗帜下，中原各诸侯国的华夏认同不断扩大，周边的戎、狄、蛮、夷在战争与交往中加速融入华夏族。赵武灵王胡服骑射主动吸收游牧民族长处，是各民族交流互鉴的著名例证。战国时期华夏族作为稳定民族共同体基本形成，为统一奠定民族基础。\",\n dimension_culture:\"百家争鸣是中国思想史上的黄金时代：孔子创立儒学（仁、礼、有教无类，弟子编《论语》）；老子著《道德经》，主张道法自然、无为而治；墨子倡兼爱、非攻；孟子讲仁政、性善、民贵君轻；荀子主张礼法并施、性恶；庄子发展道家；韩非集法家之大成，主张以法术势治国；《孙子兵法》成为世界最早的军事学著作之一。文学上《诗经》与屈原《离骚》代表的楚辞双峰并峙。私学兴起打破学在官府的垄断。\",\n dimension_science:\"生铁冶铸技术领先世界，铁制兵器与农具广泛使用。天文方面，甘德、石申的《甘石星经》记录了百余颗恒星方位，是天文学的重要成就。医学上，《黄帝内经》的理论体系在此期形成雏形。李冰父子修建都江堰，以鱼嘴分水、飞沙堰泄洪、宝瓶口引水的科学设计泽被至今；鲁班是手工业工匠的代表人物。战国司南是世界上最早的指示方向仪器雏形之一。\",\n dimension_summary:\"中国历史上思想最自由、变革最剧烈的时代：铁器牛耕引发生产力革命，进而推动宗法分封体制瓦解、官僚制与郡县制萌芽，最终由秦完成统一。百家争鸣奠定中国文化的思想基因，儒法互补的治理模式也在此时酝酿成型。\",\n world:\"同期正值轴心时代：希腊城邦民主制与哲学空前繁荣（苏格拉底、柏拉图、亚里士多德），波斯帝国扩张至地中海，印度释迦牟尼创立佛教、孔雀王朝阿育王推广佛法。东西方几大文明同时爆发出深刻的思想成果。\",\n key_event_tags:\"百家争鸣｜商鞅变法｜都江堰｜胡服骑射\",figures:\"孔子 · 老子 · 孟子 · 商鞅 · 屈原\",cause:\"铁器牛耕引发生产力革命、王权衰微\",effect:\"秦灭六国，建立第一个大一统王朝\",source_note:\"《左传》《战国策》《史记》等文献\"},\n{id:4,era:\"秦汉\",node_title:\"秦朝\",year_start:\"前221\",year_end:\"前207\",year_label:\"公元前221 — 公元前207年\",is_anchor_point:true,\n dimension_politics:\"前221年嬴政灭六国，建立中国第一个大一统的中央集权王朝。他自称始皇帝，创皇帝制度；中央设三公九卿（丞相、太尉、御史大夫分掌政、军、监察）；地方废除分封，推行郡县制，全国初设36郡，郡县长官由中央任免、不得世袭。法律细密严苛，睡虎地秦简展现其涵盖盗、贼、囚、捕、杂、具六篇的完整体系；以锐利的中央垂直管理完成对中国历史上首次的大一统治理。\",\n dimension_economy:\"统一货币为圆形方孔的半两钱；统一度量衡（以商鞅变法时的标准推广全国）；车同轨，统一车轨宽度和道路标准。经济政策上重农抑商，厉行小家庭分户以增殖税源。大规模征发民力修建驰道、直道、长城、灵渠等工程，虽然客观上促进全国经济一体化，但徭役赋税过重也埋下速亡隐患。\",\n dimension_nation:\"蒙恬北击匈奴，收复河套（河南地），将燕、赵、秦旧长城连为一体，形成西起临洮、东至辽东的万里长城；南方派屠睢、任嚣、赵佗等率军南征百越，开凿灵渠沟通湘江与漓江（长江与珠江水系），平定后设桂林、象郡、南海三郡，开发岭南。中国版图的基本轮廓由此奠定。\",\n dimension_culture:\"书同文：以小篆为标准文字统一全国文字，程邈整理的隶书也在民间流行，文字统一是维系文化认同的最重要举措。同时焚书坑儒（前213—前212），规定挟书律，开思想文化专制之端。严刑峻法与告奸制度使社会气氛紧张。\",\n dimension_science:\"全国驰道网和直道构成最早的国道体系；灵渠是世界最早的船闸式运河之一，设计巧妙；秦兵马俑被称为世界第八大奇迹，其千人千面的写实陶塑和标准化兵器（弩机部件可互换）展示了极高的工艺与组织水平。里耶秦简等出土文献证明行政文书体系运转高效。\",\n dimension_summary:\"确立中国两千余年大一统政治格局，皇帝制度、中央集权与郡县制被历代沿用，所谓百代都行秦政法。但因暴政与严刑峻法、徭役过重，仅存续15年即被陈胜吴广起义和随后的战乱推翻，其速亡也成为后世治国的重要镜鉴。\",\n world:\"同期罗马共和国正与迦太基进行三次布匿战争（前264—前146），地中海霸权尘埃未定；孔雀王朝阿育王（约前268—前232在位）推广佛教；亚历山大帝国的继业者王朝瓜分着东方。\",\n key_event_tags:\"大一统｜皇帝制｜郡县制｜书同文\",figures:\"秦始皇 · 李斯 · 蒙恬 · 赵佗\",cause:\"商鞅变法后秦国富国强兵、远交近攻\",effect:\"汉承秦制，大一统格局延续\",source_note:\"《史记·秦始皇本纪》、睡虎地秦简等\"},\n{id:5,era:\"秦汉\",node_title:\"西汉\",year_start:\"前202\",year_end:\"公元8\",year_label:\"公元前202 — 公元8年\",is_anchor_point:true,\n dimension_politics:\"汉初鉴于秦亡教训，采取郡国并行制，但诸侯势力坐大酿成七国之乱（前154）。汉武帝时颁推恩令（前127，令诸侯分封诸子以自行削弱封国）、设中朝（以尚书等近臣决策以压制相权）、置十三州部刺史监察地方，中央集权空前巩固。选官上实行察举制与征辟制，孝廉成为仕进正途。文景之治的休养生息为武帝的大规模经营积累了雄厚国力。\",\n dimension_economy:\"文景二帝轻徭薄赋、三十税一，粮价低至每石数钱；汉武帝时实行盐铁官营、均输平准（桑弘羊主持），将工商利润收归国库。张骞两次出使西域（前138、前119），丝绸之路自此开通，中国丝绸、漆器西运，长安（城内面积约36平方公里）成为国际大都会，设有专门接待外宾的蛮夷邸。\",\n dimension_nation:\"从白登之围（前200）的和亲，到汉武帝发动反击：卫青、霍去病三次大战（前127收河南地、前121收河西走廊、前119漠北决战）大破匈奴，设武威、张掖、酒泉、敦煌河西四郡；前60年设西域都护府（首任都护郑吉），天山南北正式纳入中央行政管辖。统一多民族国家的格局基本形成。\",\n dimension_culture:\"董仲舒建议罢黜百家、独尊儒术（前134），设太学（前124）与五经博士，儒学从此成为官方正统思想，贯穿此后两千余年。司马迁著《史记》，上起黄帝下至汉武帝，共52万余字，开创纪传体通史体例，被鲁迅誉为史家之绝唱，无韵之《离骚》。汉赋（司马相如《子虚赋》等）与乐府诗（《十五从军征》）各领风骚。\",\n dimension_science:\"西汉已有麻质纤维纸（灞桥纸、悬泉置纸），为蔡伦改进造纸术提供了基础；《九章算术》编成，全书246个应用问题涵盖方田、粟米、衰分、均输等九章，标志中国古代数学体系初步建立；《氾胜之书》总结了关中地区精耕细作的农业技术。\",\n dimension_summary:\"儒法合流、外儒内法的成熟帝国：儒家提供正统意识形态，法家手段维系中央集权。丝绸之路连接东西，西域都护府奠定西域归属，汉人、汉字、汉族之名由此而来，汉文化成为中华文明的主干。\",\n world:\"罗马共和国向帝国过渡（前27年奥古斯都建立元首制），环地中海商业繁荣；安息帝国（帕提亚）扼守丝绸之路中段，充当东西方贸易中介；公元前后贵霜帝国在中亚兴起。汉与罗马两大文明隔着欧亚大陆遥相辉映。\",\n key_event_tags:\"推恩令｜丝绸之路｜独尊儒术｜西域都护府\",figures:\"汉武帝 · 张骞 · 卫青 · 司马迁 · 董仲舒\",cause:\"秦速亡教训与楚汉相争的调整\",effect:\"东汉延续帝制，豪强庄园渐兴\",source_note:\"《史记》《汉书》\"},\n{id:6,era:\"秦汉\",node_title:\"东汉\",year_start:\"25\",year_end:\"220\",year_label:\"公元25 — 220年\",is_anchor_point:true,\n dimension_politics:\"公元25年刘秀建立东汉，史称光武帝。他退功臣而进文吏、加强尚书台权力，并下度田令清查土地人口，开创光武中兴；明帝、章帝继续守成，史称明章之治。但后期皇帝多幼年即位，外戚与宦官交替专权（梁冀把持朝政被称为跋扈将军），清流士人被禁锢引发两次党锢之祸（166、169），184年张角以太平道发动黄巾起义，地方豪强借镇压之机拥兵自重，东汉名存实亡。\",\n dimension_economy:\"豪强地主田庄经济发达，庄园自给自足、拥有部曲佃客。王景主持治理黄河，此后黄河约八百年间相对安流。江南地区获得初步开发，人口南迁渐启。班超经营西域三十余年（73—102），不入虎穴，焉得虎子的成语即出于此；97年甘英出使大秦（罗马）至波斯湾而返，166年大秦王安敦使者抵汉，是罗马与中国官方交往的最早记载。\",\n dimension_nation:\"班超以宽纵之策团结西域诸国，重建西域都护体系；南匈奴内附，安置于缘边八郡；羌人多次起义，西北边疆民族流动频繁；乌桓、鲜卑开始内迁。各族群在碰撞与交融中加深了与汉地的联系。\",\n dimension_culture:\"白虎观会议（79）统一五经经义。佛教经丝绸之路正式东传（明帝永平年间遣使求法，洛阳建白马寺），道教以太平道、五斗米道等民间教团形式兴起，中国宗教格局由此奠定佛道并立的底色。班固《汉书》开创纪传体断代史体例；许慎《说文解字》系统分析9353个汉字字形字义，是文字学开山之作。\",\n dimension_science:\"蔡伦于105年总结改进造纸术，以树皮、麻头、破布、旧渔网为原料制成蔡侯纸，廉价纸张从此普及，深刻改变世界知识传播方式。张衡制成浑天仪（117）和候风地动仪（138，实测陇西地震），撰《九章算术注》。医学上华佗发明麻沸散、编创五禽戏，张仲景著《伤寒杂病论》，奠定中医辨证论治基础，被尊为医圣。\",\n dimension_summary:\"帝国由盛转衰的过渡期：外戚宦官循环致政局败坏、豪强坐大终致分裂，但蔡伦造纸、佛教东传、中医体系确立三大变革深刻影响此后两千年，四百年的汉家气象也塑造了华夏族群的自我认同。\",\n world:\"罗马帝国进入五贤帝时代（96—180），图拉真时期版图达到最大；贵霜帝国迦腻色伽王崇佛，犍陀罗艺术兴盛。汉、罗马、安息、贵霜四大帝国并立于欧亚大陆，通过丝绸之路相联系。\",\n key_event_tags:\"光武中兴｜造纸术｜佛教东传｜黄巾起义\",figures:\"光武帝 · 班超 · 蔡伦 · 张衡 · 张仲景\",cause:\"王莽篡汉引发乱世、光武中兴\",effect:\"汉末分裂为三国，佛教在中国扎根\",source_note:\"《后汉书》《东观汉记》《说文解字》\"},\n{id:7,era:\"魏晋南北朝\",node_title:\"三国两晋南北朝\",year_start:\"220\",year_end:\"589\",year_label:\"公元220 — 589年\",is_anchor_point:true,\n dimension_politics:\"曹丕代汉（220）、刘备称帝（221）、孙权称帝（229），三国鼎立；西晋280年短暂统一，八王之乱后永嘉之乱（311）政权南渡，形成东晋与十六国、南朝（宋齐梁陈）与北朝（北魏、东西魏、北齐、北周）长期对峙。九品中正制使门阀士族垄断仕途，形成上品无寒门、下品无势族的门阀政治。北魏孝文帝厉行改革：485年颁均田令，494年迁都洛阳，全面推行汉化，为北方再统一奠定基础。\",\n dimension_economy:\"永嘉之乱后北方战乱频仍，大量人口衣冠南渡，带来劳动力和先进技术，江南得到大规模开发（史称南朝江东殷实），经济重心南移自此起步。北方则由北魏推行均田制与租调制，将荒地分配给农民、恢复农业生产，长期分裂下经济依然在缓慢复苏。\",\n dimension_nation:\"匈奴、鲜卑、羯、氐、羌五胡内迁，与汉民族在北方杂居融合。孝文帝改革是民族交融的标志：迁都洛阳、改汉姓（拓跋改姓元）、禁胡语胡服、鼓励与汉人通婚、沿用汉制。经过两百余年大迁徙、大融合，中华民族共同体在碰撞中扩大，中华认同在多元中深化。\",\n dimension_culture:\"玄学清谈（何晏、王弼至竹林七贤）使老庄思想复兴；佛教大盛，法显西行取经，云冈、龙门石窟相继开凿，寺院经济膨胀；道教经葛洪、陶弘景重构走向成熟。文学艺术群星璀璨：建安风骨、陶渊明开创田园诗，书圣王羲之《兰亭序》被誉为天下第一行书，顾恺之《洛神赋图》以形写神，《木兰辞》《敕勒歌》流传北地。民歌、志怪小说（《搜神记》）各放异彩。\",\n dimension_science:\"贾思勰《齐民要术》是现存最早最完整的农书，系统总结了北方农业与食品加工技术；祖冲之推算圆周率精确至3.1415926与3.1415927之间，领先世界近千年，并编制《大明历》；郦道元《水经注》记载河流千余条，兼具地理与文学价值；马钧改进翻车（龙骨水车）；裴秀提出制图六体，奠定中国制图学理论。\",\n dimension_summary:\"近四百年的分裂中孕育着统一：民族大融合重塑了中华共同体，江南开发奠定了经济重心南移的起点，均田制、府兵制等制度创新为隋唐盛世铺平道路。这是动荡时代，也是承前启后的时代。\",\n world:\"476年西罗马帝国灭亡，欧洲进入中世纪；拜占庭帝国查士丁尼主持编订《民法大全》（529—534），并兴建圣索菲亚大教堂；萨珊波斯与拜占庭长期拉锯；佛教沿丝路东传进入鼎盛期，在朝鲜半岛与日本列岛播撒种子。\",\n key_event_tags:\"民族大融合｜孝文帝改革｜江南开发｜均田制\",figures:\"曹操 · 诸葛亮 · 孝文帝 · 王羲之 · 祖冲之\",cause:\"东汉崩溃、八王之乱与五胡内迁\",effect:\"隋朝再造大一统\",source_note:\"《三国志》《晋书》《魏书》《齐民要术》\"},\n{id:8,era:\"隋唐\",node_title:\"隋朝\",year_start:\"581\",year_end:\"618\",year_label:\"公元581 — 618年\",is_anchor_point:true,\n dimension_politics:\"581年杨坚代周建隋，589年灭陈，结束近四百年分裂。制度上全面创新：三省六部制臻于完备（中书出令、门下封驳、尚书执行，六部分管政务，相权一分为三）；开创科举制（隋炀帝设进士科，以考试成绩选官，取代九品中正制）；整顿府兵制；颁布宽平简要的《开皇律》。这些制度框架为唐所全面继承。\",\n dimension_economy:\"大运河是隋朝最伟大的工程遗产：605年起先后开凿通济渠、邗沟、永济渠、江南河，贯通海河、黄河、淮河、长江、钱塘江五大水系，全长2700余公里，沟通南北经济命脉，故有尽道隋亡为此河之叹。沿河设含嘉仓、回洛仓等大型官仓，实行义仓备荒；输籍定样整顿户籍，国家掌握了大量税源。\",\n dimension_nation:\"平陈统一南北；对突厥施以分化之策，扶植启民可汗稳定北疆；炀帝西巡张掖，会见西域诸国使者，设西海、河源等郡，重开丝路。虽享国短促，但为唐代的民族大格局搭好了舞台。\",\n dimension_culture:\"大兴城（今西安）由宇文恺规划，面积约84平方公里，是当时世界最大都城，里坊规整、中轴对称，成为后世都城建设的典范；东都洛阳同样气象恢弘。雕版印刷术在此期萌芽。炀帝营建的洛阳与运河沿线的繁华市镇，孕育着商业文明的新因素。\",\n dimension_science:\"大运河是一项超越时代的系统工程，其船闸、堤堰设计体现了高超的水利技术；李春设计建造的赵州桥（约605年）是世界现存最古老的敞肩石拱桥，单孔跨径37米，历经千年洪水地震仍巍然屹立，比欧洲同类桥梁早七百余年。\",\n dimension_summary:\"短命而伟大的枢纽王朝：与秦朝一样，二世而亡（因暴政与滥用民力），但其制度遗产（三省六部、科举）与工程遗产（大运河、赵州桥、大兴城）被唐全面继承，是再造大一统的关键转折点。\",\n world:\"拜占庭帝国与萨珊波斯连年鏖战；610年穆罕默德开始在麦加传教，622年迁往麦地那（伊斯兰历元年），阿拉伯帝国即将崛起并深刻改变欧亚格局。\",\n key_event_tags:\"大运河｜科举制｜三省六部｜赵州桥\",figures:\"隋文帝 · 隋炀帝 · 宇文恺 · 李春\",cause:\"北朝整合南北、民族融合完成\",effect:\"唐承隋制，走向盛世\",source_note:\"《隋书》《资治通鉴》\"},\n{id:9,era:\"隋唐\",node_title:\"唐朝\",year_start:\"618\",year_end:\"907\",year_label:\"公元618 — 907年\",is_anchor_point:true,\n dimension_politics:\"唐朝经历贞观之治（627—649，唐太宗虚心纳谏、任用魏征等贤臣）与开元盛世（713—741，杜甫忆昔开元全盛日）两个高峰。三省六部与科举制走向成熟，武则天创殿试、开武举。755年安史之乱爆发，历时八年方平，此后藩镇割据、宦官专权（甘露之变）、牛李党争交织，帝国由盛转衰。唐律疏议是中华法系的代表法典。\",\n dimension_economy:\"前期实行租庸调制，780年杨炎推行两税法（量出制入、按资产征税），是中国赋税制度的重大转折。长安城人口百万、面积84平方公里，是当时世界最大的国际大都会；广州通海夷道远达波斯湾，市舶外贸兴盛；金融上出现飞钱（汇兑凭证）与柜坊（存贷机构）。饮茶之风盛行，茶马贸易兴起。\",\n dimension_nation:\"唐太宗被北方各族尊为天可汗，构建以唐为中心的东亚国际秩序；设安西、北庭都护府经营西域；文成公主入藏（641，嫁松赞干布）、金城公主入藏（710），汉藏和好，唐蕃会盟碑至今屹立拉萨；回纥助唐平乱，南诏、渤海国（海东盛国）与唐保持密切联系。开放包容的民族政策是大唐气象的重要内涵。\",\n dimension_culture:\"唐诗登峰造极，存诗五万余首：李白豪放飘逸为诗仙，杜甫沉郁顿挫为诗圣，白居易通俗晓畅。书法上欧阳询、颜真卿、柳公权楷书三峰并立，张旭、怀素草书狂放。玄奘西行取经（629—645）著《大唐西域记》，鉴真六次东渡传戒日本；长安胡风盛行，胡乐、胡舞、胡食、胡服风靡，万国来朝，是开放包容的世界性帝国。\",\n dimension_science:\"868年刻印的《金刚经》是现存最早的标年雕版印刷品；火药配方在唐代炼丹著作中首次见于文字记载；僧一行（725年前后）主持实测子午线长度、编制《大衍历》；659年颁行的《唐本草》是世界第一部由国家颁布的药典。雕版印刷、火药、医药学的高峰都在唐代出现。\",\n dimension_summary:\"中华帝国的黄金时代：制度成熟、经济繁荣、文化自信、国际开放。安史之乱虽使盛唐急转直下，但唐诗、书法、佛教中国化和向外传播的文明成就，使盛唐气象成为中华文明最具辨识度的名片之一。\",\n world:\"阿拉伯帝国迅速崛起并横跨欧亚非，751年怛罗斯之战与唐相遇，中国的造纸术经此西传；800年查理曼加冕，欧洲进入加洛林时代；日本大化改新（645）全面学习唐朝制度，形成东亚文化圈。\",\n key_event_tags:\"贞观之治｜开元盛世｜安史之乱｜天可汗\",figures:\"唐太宗 · 武则天 · 李白 · 杜甫 · 玄奘\",cause:\"隋末民乱与制度遗产的整合\",effect:\"藩镇格局延续，宋代转向崇文抑武\",source_note:\"《旧唐书》《新唐书》《资治通鉴》\"},\n{id:10,era:\"辽宋夏金\",node_title:\"两宋\",year_start:\"960\",year_end:\"1279\",year_label:\"公元960 — 1279年\",is_anchor_point:true,\n dimension_politics:\"960年赵匡胤发动陈桥兵变建立宋朝，随即杯酒释兵权解除宿将兵权，确立崇文抑武的国策（士大夫与天子共治天下）。中央实行二府三司制：中书门下主政、枢密院主军、三司主财，台谏系统监督，权力分立严密。范仲淹庆历新政（1043）与王安石变法（1069，青苗法、募役法、市易法、保甲法等）试图挽救积贫积弱，但均遭挫折。1127年靖康之变金军攻破汴京，宋室南渡，与金以淮河—大散关为界偏安江南（1141年绍兴和议）。\",\n dimension_economy:\"发生了被许多学者称为商业革命的巨变：1024年官发的交子是世界最早的纸币；打破坊市界限，夜市、早市、瓦子勾栏昼夜喧阗；设市舶司（广州、泉州、明州）管理海外贸易，泉州成为世界东方第一大港；货币流通量巨大，商税与专卖收入超过农业税。《清明上河图》描绘的汴京是中国古代城市商业繁荣的生动缩影。\",\n dimension_nation:\"与辽、西夏、金等政权长期对峙并存：1005年澶渊之盟后宋辽百年和平（岁币三十万）；1141年绍兴和议后宋金对峙。多民族政权在碰撞中加深交融：契丹、党项、女真主动学习汉制，汉文化辐射四邻。海上丝绸之路取代陆路成为对外交流主通道，泉州、广州汇聚各国商人。\",\n dimension_culture:\"程朱理学形成完整体系（二程、朱熹，朱熹《四书章句集注》后为科举定本），书院兴盛（白鹿洞、岳麓、嵩阳、应天府四大书院）；宋词与唐诗并称双璧（柳永的市井风情、苏轼的豪放旷达、李清照的婉约清丽、辛弃疾的慷慨悲歌）；张择端《清明上河图》、司马光《资治通鉴》（294卷编年体通史）皆为传世巨制；毕昇庆历年间（1041—1048）发明活字印刷术。宋代文化重理性、重世俗、重市民趣味。\",\n dimension_science:\"古代科技的巅峰：指南针用于航海（朱彧《萍洲可谈》首次记载），火药武器化（突火枪等），活字印刷三大发明在此期成熟应用；沈括《梦溪笔谈》609条笔记涉及天文、数学、物理、地质，被誉为中国科学史的坐标；苏颂水运仪象台（1092）是世界最早的天文钟；《营造法式》（李诫，1103）是建筑学的经典规范。\",\n dimension_summary:\"军事相对弱势而经济、文化、科技臻于中国历史的巅峰：纸币、城市革命、市民社会与现代性曙光在此期初现，其文明成就为世界瞩目。多政权并立的格局也体现了这一时期民族交融的时代特征。\",\n world:\"十字军东征（1096—1291）搅动地中海；欧洲中世纪盛期城市与商业复兴，博洛尼亚大学（1088）等中世纪大学兴起；1206年成吉思汗统一蒙古高原，蒙古帝国的扩张即将席卷欧亚大陆。\",\n key_event_tags:\"交子｜澶渊之盟｜程朱理学｜活字印刷\",figures:\"宋太祖 · 王安石 · 苏轼 · 岳飞 · 朱熹 · 沈括\",cause:\"唐末藩镇割据与五代武人政治的反动\",effect:\"元灭南宋，大一统重现\",source_note:\"《宋史》《东京梦华录》《梦溪笔谈》《资治通鉴》\"},\n{id:11,era:\"元明清\",node_title:\"元朝\",year_start:\"1271\",year_end:\"1368\",year_label:\"公元1271 — 1368年\",is_anchor_point:true,\n dimension_politics:\"1271年忽必烈定国号为元，1279年灭南宋，实现中国历史上又一次大一统，也是首个由少数民族建立的大一统王朝。制度上创立行省制度：中书省直辖腹里，地方设岭北、辽阳、甘肃、云南等十个行省，行省制沿用至今，是中国省制的开端。设宣政院管理西藏和佛教事务（帝师领院事）；长期实行四等人制（蒙古、色目、汉人、南人），民族歧视色彩浓厚。全国设站赤（驿站）约1500处，政令军报传递迅速。\",\n dimension_economy:\"大运河截弯取直（开凿会通河、通惠河），南北漕运直达；同时开辟刘家港至直沽的海上漕运，海运与河运并行。驿站体系（站赤）四通八达，东西商旅、使节往来畅通，欧亚大陆贸易空前繁荣。泉州作为世界大港享誉海外，马可·波罗称其为光明之城。匠户制度使官营手工业保持规模。\",\n dimension_nation:\"设宣政院管辖吐蕃地区，西藏正式纳入中央行政版图，这是中国统一多民族国家发展史上的大事；设澎湖巡检司管理澎湖与台湾（琉球）事务；云南正式建省（赛典赤治滇），岭北行省辖及西伯利亚南部。来自西域的各族人口在内地定居，与汉、蒙古等民族融合，逐渐形成回回民族。大规模人口迁徙与杂居使各民族深度交融。\",\n dimension_culture:\"元曲兴盛，代表城市市民文化的繁荣：关汉卿《窦娥冤》、王实甫《西厢记》、马致远《天净沙·秋思》皆为经典；黄公望《富春山居图》是文人画高峰；文天祥以《正气歌》《过零丁洋》名垂青史。马可·波罗游记在欧洲激起对东方的向往；景教（基督教聂斯脱里派）与伊斯兰教在华传播，文化多元。书院在元代继续存续发展。\",\n dimension_science:\"郭守敬编《授时历》（1281年颁行），定回归年长度为365.2425天，与现行格里高利历相同精度但早三百年，是古代最精密的历法之一；他改进的简仪等天文仪器领先世界。王祯《农书》全面总结南北农政，附转轮排字法推广木活字。黄道婆自海南归来改良棉纺织技术（乌泥泾被），棉布逐步取代麻布成为大众衣料。火器技术经战场与商路西传，深刻影响世界军事史。\",\n dimension_summary:\"世界帝国的中国篇：疆域空前辽阔，行省制度影响至今，西藏正式纳入版图，东西交通大开。元朝打通了欧亚大陆的文化与贸易通道，中国与世界的联系空前紧密，也是世界格局大变动中的一环。\",\n world:\"蒙古帝国横跨欧亚，四大汗国并立；1258年旭烈兀攻陷巴格达，灭阿拔斯王朝；马可·波罗1275—1292年在中国任职游历；但丁《神曲》（1308—1320）标志欧洲文艺复兴前夜的到来。欧亚大陆因蒙古治下和平而交通空前。\",\n key_event_tags:\"行省制｜宣政院｜澎湖巡检司｜元曲\",figures:\"成吉思汗 · 忽必烈 · 郭守敬 · 文天祥\",cause:\"蒙古迅速崛起、灭金亡宋\",effect:\"明承元制，东西方联系空前\",source_note:\"《元史》《马可·波罗行纪》《授时历》\"},\n{id:12,era:\"元明清\",node_title:\"明朝\",year_start:\"1368\",year_end:\"1644\",year_label:\"公元1368 — 1644年\",is_anchor_point:true,\n dimension_politics:\"1368年朱元璋建立明朝，年号洪武。1380年借胡惟庸案废除丞相制度，权分六部，皇帝亲掌大政；永乐以后内阁逐渐成形，嘉靖、隆庆、万历年间首辅以票拟之权实际主持政务；锦衣卫、东厂、西厂等厂卫特务机构直接听命于皇帝，君主专制空前强化。张居正改革推行考成法整顿吏治，1581年一条鞭法合并赋役、折银征收。明代宦官参政（司礼监批红）与文官集团形成长期博弈。\",\n dimension_economy:\"白银货币化是明代经济最重要的变化：隆庆开关（1567）开放月港，海外白银大量流入，中国被卷入全球贸易网络。江南市镇手工业繁荣，苏州等地的丝织业中出现以机户出资、机工出力为特征的雇佣关系，被学界视为资本主义萌芽的讨论焦点。徽商、晋商等商帮崛起，会馆遍布全国。\",\n dimension_nation:\"设奴儿干都司管辖东北；设乌思藏都司管理西藏；封授女真、蒙古、西藏各部首领。郑和七下西洋（1405—1433），宝船船队最远达非洲东海岸和红海沿岸，是世界航海史上的空前壮举，早于哥伦布近九十年。戚继光、俞大猷等抗倭名将平定东南沿海倭患（1560年代）。明末利玛窦与徐光启合译《几何原本》，中西文化交流再次相遇。\",\n dimension_culture:\"《永乐大典》（1408年成书，11095册）是世界罕见的类书巨制。王阳明心学（致良知、知行合一）突破程朱理学一统的局面；李贽以《焚书》抨击正统，离经叛道。文学世俗化达到高峰：《三国演义》《水浒传》《西游记》等长篇小说名作相继问世，《牡丹亭》是昆曲的巅峰之作。书法绘画上吴门四家、董其昌各领风骚。\",\n dimension_science:\"晚明出现三部科学巨著：李时珍《本草纲目》（1578，收药1892种，达尔文曾引用），徐光启《农政全书》，宋应星《天工开物》（1637，被誉为中国17世纪的工艺百科全书）；徐霞客游记对喀斯特地貌的考察领先世界。《崇祯历书》引进西方天文学。这一时期传统科技与西方科学开始交汇。\",\n dimension_summary:\"传统帝制的定型与巅峰：废丞相、设内阁、行厂卫，专制皇权登峰造极；郑和下西洋是帝制晚期的开放绝响，白银货币化则将中国深度卷入全球化。晚明思想解放与科学巨著提示着转型可能，但王朝最终在内外交困中崩塌。\",\n world:\"欧洲开启地理大发现：哥伦布1492年抵达美洲，麦哲伦船队1519—1522完成首次环球航行；1517年马丁·路德发起宗教改革；文艺复兴进入盛期（达·芬奇、米开朗琪罗）；1588年西班牙无敌舰队覆灭，英国崛起。世界从此逐渐连为一体。\",\n key_event_tags:\"郑和下西洋｜废丞相｜一条鞭法｜心学\",figures:\"朱元璋 · 张居正 · 郑和 · 王阳明 · 李时珍 · 徐光启\",cause:\"元末民变、驱逐胡虏重建汉人王朝\",effect:\"明亡清兴，王朝循环继续\",source_note:\"《明史》《明实录》《天工开物》《本草纲目》\"},\n{id:13,era:\"元明清\",node_title:\"清朝（前期）\",year_start:\"1636\",year_end:\"1840\",year_label:\"公元1636 — 1840年\",is_anchor_point:true,\n dimension_politics:\"康雍乾盛世（1662—1796）是中国帝制时代最后一个盛世。雍正设军机处（1729），军国大事由皇帝一人裁夺，君主专制达到顶峰；密折制度使官员互相监督。同时大兴文字狱（庄氏明史案、吕留良案等），钳制思想；延续八股取士。对外厉行闭关政策，社会气氛趋于保守。\",\n dimension_economy:\"摊丁入亩（1712—1729年逐步推行）废除人头税，人口迅速增长，道光时突破四亿；玉米、甘薯等高产作物推广支撑了人口膨胀。对外贸易由广州十三行一口通商（1757年起），严格限制中外往来；晋商票号（日升昌等）开创近代金融雏形。农业精耕细作达到传统极致，但生产技术未见根本突破。\",\n dimension_nation:\"经过康雍乾三代平定准噶尔（1759年平定大小和卓），设驻藏大臣（1727）、金瓶掣签（1793）稳定西藏，多伦会盟（1691）与盟旗制度安顿蒙古，雍正朝改土归流经营西南；1689年《尼布楚条约》是第一个边界条约；1771年土尔扈特部在渥巴锡率领下万里东归。清朝前期的经营奠定了现代中国的版图（极盛时约1300万平方公里），统一多民族国家最终定型。\",\n dimension_culture:\"《四库全书》（1782年成书，收书3500余种）是最大的丛书工程，但编纂中毁禁了一批违碍书籍。乾嘉考据学（戴震等）达到传统学术巅峰；《红楼梦》（曹雪芹）代表古典小说最高成就，《聊斋志异》《儒林外史》各具光彩；1790年徽班进京，京剧在融合中渐成；纳兰性德的词享有盛名。\",\n dimension_science:\"传统科技体系趋于缓慢，与西方近代科学的差距拉大。康熙朝曾引入西学，梅文鼎、明安图等历算名家辈出，1718年完成《皇舆全览图》实测；但西学仅限宫廷，未及社会层面。戴梓所造连珠铳等火器未获推广，军事技术与西方的差距在此期间悄然拉开。\",\n dimension_summary:\"多民族统一国家的最终定型：今日中国版图的基本轮廓在清朝前期奠定，康乾盛世展示了帝制时代的最后辉煌。但军机处的极端专制、文字狱的思想禁锢与闭关锁国的对外政策，使中国在工业革命的世界大潮中渐趋封闭，为近代的落后挨打埋下伏笔。\",\n world:\"英国工业革命（约1760年起，瓦特蒸汽机1769年取得专利）；1776年美国独立；1789年法国大革命爆发。西方在政治革命与工业革命的双重驱动下加速转型，与清朝的停滞形成鲜明对照。\",\n key_event_tags:\"康乾盛世｜军机处｜驻藏大臣｜闭关锁国\",figures:\"康熙 · 雍正 · 乾隆 · 曹雪芹 · 戴震\",cause:\"明末内乱与清军入关\",effect:\"国势与西方差距拉大，走向鸦片战争\",source_note:\"《清史稿》《清实录》《四库全书总目》\"},\n{id:14,era:\"晚清\",node_title:\"晚清\",year_start:\"1840\",year_end:\"1912\",year_label:\"公元1840 — 1912年\",is_anchor_point:true,\n dimension_politics:\"1840年鸦片战争爆发，中国开始沦为半殖民地半封建社会：1842年《南京条约》（割香港岛、五口通商、赔款2100万银元、协定关税）破坏了领土与主权完整；1895年《马关条约》（割台湾澎湖、赔款两亿两、允许外国设厂）大大加深民族危机；1901年《辛丑条约》（赔款4.5亿两、本息合计9.8亿两、设使馆区）使清政府成为洋人的朝廷。救亡图存的尝试接连不断：洋务运动（1861—1895）、戊戌变法（1898百日维新）、清末新政与预备立宪（1908《钦定宪法大纲》、1911皇族内阁），最终都未能挽救危局。\",\n dimension_economy:\"洋务运动兴办近代企业：江南制造总局（1865）、福州船政局、轮船招商局、开平矿务局、汉阳铁厂等，近代工业起步；民族资本主义（发昌机器厂等）在一战前后初步发展。通商口岸率先近代化，上海迅速崛起；但海关行政长期由外籍总税务司（赫德）把持，对外贸易主权旁落，赔款负担沉重。\",\n dimension_nation:\"甲午战败后列强掀起瓜分狂潮（1897—1899强租租借地、划分势力范围）。左宗棠收复新疆（1876—1878）并于1884年建省；台湾于1885年建省，1895年后被日本割占50年；美国1899年提出门户开放政策。民族危机催生了各阶层的抗争：三元里抗英、太平天国、义和团运动、辛亥革命此起彼伏。\",\n dimension_culture:\"开眼看世界：魏源《海国图志》倡师夷长技以制夷；严复译《天演论》（1897—1898）以物竞天择警醒国人；冯桂芬《校邠庐抗议》、郑观应《盛世危言》探讨变法图强。1898年京师大学堂创立；1905年废除延续1300年的科举制度，新式学堂与新学制（癸卯学制）逐步建立；报刊（《申报》《时务报》）与出版业兴起。\",\n dimension_science:\"洋务运动引进近代工业与军事技术，设江南制造局翻译馆译介西方科技；詹天佑主持修建京张铁路（1905—1909），以人字形线路攻克八达岭险峻地形，是中国人自行设计施工的第一条铁路；近代医学（如协和医学堂1906）与高等教育开始起步。\",\n dimension_summary:\"三千年未有之大变局：不平等条约体系使中国一步步沦为半殖民地半封建社会，屈辱与抗争并存。从器物（洋务）到制度（维新、立宪）再到思想（民主科学），各阶层探索不断深化，最终由辛亥革命推翻帝制、走向共和。\",\n world:\"第二次工业革命（电气化、内燃机、化工）完成，帝国主义列强瓜分世界（1884年柏林会议瓜分非洲）；同盟体系剑拔弩张，1914年第一次世界大战即将爆发。中国在殖民体系中被动卷入全球资本主义网络。\",\n key_event_tags:\"鸦片战争｜洋务运动｜戊戌变法｜辛亥革命\",figures:\"林则徐 · 李鸿章 · 左宗棠 · 康有为 · 詹天佑\",cause:\"闭关自守与工业革命的落差\",effect:\"辛亥革命爆发，帝制终结\",source_note:\"《筹办夷务始末》及中外条约文献\"},\n{id:15,era:\"民国\",node_title:\"中华民国\",year_start:\"1912\",year_end:\"1949\",year_label:\"公元1912 — 1949年\",is_anchor_point:true,\n dimension_politics:\"1911年10月10日武昌起义，辛亥革命推翻两千年帝制；1912年1月1日中华民国建立，孙中山任临时大总统，颁布《临时约法》。此后袁世凯窃国、军阀混战（直、皖、奉系）；1924年国共第一次合作，1926—1928年北伐；1931年九一八事变日本侵占东北，1937年七七事变全面抗战爆发；全民族抗战八年（1931—1945年局部抗战十四年），1945年胜利后国共内战（1946—1949），1949年10月1日中华人民共和国成立，民国时期终结。\",\n dimension_economy:\"第一次世界大战期间列强暂时放松侵略，民族工业迎来短暂春天（纺织、面粉业尤盛）；1927年后南京国民政府推进十年建设，1935年法币改革统一币制。抗战时期沿海工业大规模内迁，西南后方经济艰难支撑；后期官僚资本急剧膨胀，民生凋敝，恶性通货膨胀加速了国民政府的崩溃。\",\n dimension_nation:\"民国建立后提出五族共和的理念；1932年日本扶植伪满洲国，妄图分裂中国。抗日战争中全民族抗日民族统一战线形成，各民族共赴国难，中华民族意识空前觉醒。中国政府逐步收回部分租界（1927年收回汉口、九江英租界）；1943年《开罗宣言》确认台湾归还中国；中国成为联合国创始会员国和安理会常任理事国，国际地位根本改变。\",\n dimension_culture:\"新文化运动（1915年《新青年》，陈独秀、胡适、鲁迅为代表）高举民主与科学大旗，白话文取代文言文成为书写主流；鲁迅《狂人日记》是现代文学的开山之作。1919年五四运动标志着新民主主义革命的开端，马克思主义经李大钊《我的马克思主义观》等广泛传播。抗战时期西南联大（1938—1946）弦歌不辍，保存了教育文化火种。\",\n dimension_science:\"1915年中国科学社创办《科学》杂志；1928年中央研究院成立，中国现代科研体制初步建立；侯德榜联合制碱法（1940年代）是世界制碱技术的重要突破。抗战期间高校与科研机构西迁坚持教学科研（浙江大学文军长征），培养了大批科学人才。\",\n dimension_summary:\"从帝制到共和的剧烈转型期：辛亥革命终结帝制但未改变半殖民地地位，五四运动后救亡图存与思想启蒙并行，抗日战争铸就民族觉醒，最终在解放战争中完成了从旧中国到新中国的历史转折。\",\n world:\"第一次世界大战（1914—1918）与凡尔赛—华盛顿体系重塑国际格局；1929年大萧条波及全球，助长法西斯主义；第二次世界大战（1939—1945）彻底改变世界；1945年联合国成立，冷战随即开启。二十世纪上半叶的世界剧烈动荡，中国与世界的命运紧密相连。\",\n key_event_tags:\"辛亥革命｜五四运动｜抗日战争｜新中国成立\",figures:\"孙中山 · 鲁迅 · 李大钊 · 毛泽东\",cause:\"清廷改良失败与革命思潮兴起\",effect:\"中华人民共和国成立，历史翻开新页\",source_note:\"《中国近代史》相关研究与档案文献\"},\n{id:16,era:\"新中国\",node_title:\"新中国 · 奠基期\",year_start:\"1949\",year_end:\"1978\",year_label:\"公元1949 — 1978年\",is_anchor_point:true,\n dimension_politics:\"1949年10月1日开国大典宣告中华人民共和国成立。1949年《共同纲领》代行宪法职能，1954年第一部宪法颁布、人民代表大会制度确立；1956年完成对农业、手工业和资本主义工商业的社会主义改造（一化三改），社会主义基本制度确立。1951年西藏和平解放；1950—1953年抗美援朝保卫了新中国的安全。这一时期也经历了文化大革命等曲折探索，1978年前后的历史转折为改革开放积蓄了经验教训。\",\n dimension_economy:\"第一个五年计划（1953—1957）以156项重点工程为核心，鞍山钢铁、长春第一汽车制造厂、武汉长江大桥等相继建成，独立的工业体系初步建立。其间经历大跃进（1958—1960）的挫折，国民经济经调整（八字方针）恢复发展。土地改革（1950—1952）废除封建土地所有制，三亿多农民分得土地，农业生产力得到解放。\",\n dimension_nation:\"民族区域自治制度确立（五个自治区相继成立），各民族平等团结。外交上提出和平共处五项原则（1953—1954），1955年周恩来率团出席万隆会议，广泛团结亚非国家；1971年恢复在联合国的一切合法权利；1972年尼克松访华、中日建交，打开外交新局面。\",\n dimension_culture:\"大规模扫盲运动使文盲率大幅下降；1958年《汉语拼音方案》颁行，便利了汉字学习与推广普通话；1956年提出百花齐放、百家争鸣的双百方针。《义勇军进行曲》定为国歌；学雷锋活动蔚然成风，两弹一星精神、焦裕禄精神等成为时代强音。\",\n dimension_science:\"两弹一星成就辉煌：1964年第一颗原子弹爆炸成功，1967年氢弹试验成功，1970年东方红一号卫星升空，钱学森、邓稼先、郭永怀等科学家隐姓埋名铸就大国重器。1965年人工合成结晶牛胰岛素为世界首次；袁隆平1973年实现籼型杂交水稻三系配套，1972年屠呦呦团队发现青蒿素，造福世界。\",\n dimension_summary:\"站起来的奠基期：主权独立、制度框架、工业底子与大国地位基本确立，为后来的改革开放准备了条件。探索中既有伟大成就，也经历了曲折，正反两方面的经验都成为宝贵财富。\",\n world:\"冷战两极格局对峙（北约1949、华约1955）；朝鲜战争、越南战争牵动亚洲；亚非拉民族独立浪潮席卷全球，不结盟运动兴起；1971—1972年中美关系正常化进程开启，世界格局酝酿新变化。\",\n key_event_tags:\"开国大典｜一五计划｜两弹一星｜恢复联合国席位\",figures:\"毛泽东 · 周恩来 · 钱学森 · 邓稼先 · 袁隆平\",cause:\"抗战胜利与解放战争的结局\",effect:\"十一届三中全会开启改革开放\",source_note:\"《中华人民共和国史》及官方文献\"},\n{id:17,era:\"新中国\",node_title:\"新中国 · 改革开放与新时代\",year_start:\"1978\",year_end:\"至今\",year_label:\"公元1978年 — 至今\",is_anchor_point:true,\n dimension_politics:\"1978年十一届三中全会作出把工作重心转移到经济建设上来、实行改革开放的历史性决策。一国两制构想成功落地：1997年7月1日香港回归、1999年12月20日澳门回归。全面依法治国深入推进，完善中国特色社会主义法治体系；全过程人民民主不断发展；2021年全面建成小康社会，开启全面建设社会主义现代化国家新征程。\",\n dimension_economy:\"从经济特区试点（1980年深圳、珠海、汕头、厦门）到社会主义市场经济体制确立（1992年十四大），再到加入世界贸易组织（2001年12月11日），中国深度融入全球经济。2010年成为世界第二大经济体；2021年脱贫攻坚战全面胜利，近一亿农村贫困人口摆脱绝对贫困；中国已是全球最大货物贸易国和140多个国家和地区的主要贸易伙伴。\",\n dimension_nation:\"一国两制成功实践保障港澳繁荣稳定；西部大开发（2000年启动）、对口支援促进区域协调和民族地区发展；2013年提出的一带一路倡议已有150多个国家参与合作，全球发展倡议等中国方案为世界治理贡献力量。中华民族共同体意识不断铸牢。\",\n dimension_culture:\"1977年恢复高考，尊重知识、尊重人才蔚然成风。2008年北京奥运会向世界展示开放中国；2022年北京冬奥会使其成为首个双奥之城。文化产业繁荣，非物质文化遗产保护体系建立；人类命运共同体理念、全球文明倡议贡献中国智慧。文化自信成为更基本、更深沉、更持久的力量。\",\n dimension_science:\"载人航天实现跨越：2003年杨利伟乘神舟五号进入太空，2021—2022年中国空间站全面建成；探月工程嫦娥系列持续突破（2024年嫦娥六号实现月背采样返回）；2021年天问一号着陆火星；2020年北斗全球组网；高铁营业里程超4万公里居世界第一；港珠澳大桥、国产大飞机C919（2023年商业首航）、5G、超级计算机、人工智能等领域跻身世界前列。\",\n dimension_summary:\"从富起来到强起来：改革开放四十余年，中国在与世界的深度互动中实现历史性跨越，正向着全面建成社会主义现代化强国的目标迈进，民族复兴进入不可逆转的历史进程。\",\n world:\"1991年冷战结束，世界多极化与经济全球化并行发展；信息化、人工智能革命深刻改变生产生活方式；气候变化、公共卫生等全球性挑战需要各国携手应对。世界正经历百年未有之大变局。\",\n key_event_tags:\"改革开放｜一国两制｜加入WTO｜复兴\",figures:\"邓小平 · 袁隆平 · 屠呦呦\",cause:\"文革结束、真理标准问题大讨论\",effect:\"持续深化改革开放，走向复兴（进行中）\",source_note:\"《关于建国以来党的若干历史问题的决议》及政府公报\"}\n];\nconst SCENES = {\n 1:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_8ad39e238c154c489b6a70d1fc51881a.png\",alt:\"良渚文化玉琮\"},\n 2:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_869269bd403945e79b1a41e02c7674cc.jpg\",alt:\"商代司母戊鼎\"},\n 3:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_34a297768370489ca452b24d64f0219b.jpg\",alt:\"都江堰水利工程\"},\n 4:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_583640a89efb409ca13e4e5bc603be9e.jpg\",alt:\"秦始皇兵马俑军阵\"},\n 5:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_6534bd51108648ac9ffb4de95aa2e2df.jpg\",alt:\"丝绸之路驼队与敦煌壁画\"},\n 6:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_98f630989dce47be9c7d45d9f6ddd6be.png\",alt:\"洛阳白马寺\"},\n 7:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_0e274643329d420babe60ac2e88891d1.jpg\",alt:\"龙门石窟卢舍那大佛\"},\n 8:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_4e7842d6c0554ee6bbf192df5e640bf5.jpg\",alt:\"赵州桥\"},\n 9:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_e9dfa802014c429c977eb4a27e927a04.jpg\",alt:\"西安大雁塔\"},\n 10:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_dbc2c720b3124c3d9133b6f2364acb8d.jpg\",alt:\"清明上河图中的汴京\"},\n 11:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_5a422b9711c7432bb546307d9c2068f8.jpg\",alt:\"京杭大运河上的拱宸桥\"},\n 12:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_3ff4bf6a866a490bbcca395bba7461e0.jpg\",alt:\"北京故宫太和殿\"},\n 13:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_aad5bc387f854d9cb17ed9c7121cb067.jpg\",alt:\"承德避暑山庄\"},\n 14:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_f7c138aaef004be1b71ccbde6082820a.jpg\",alt:\"圆明园大水法遗址\"},\n 15:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_206bf0a5ea3848f78e9641c6dd45690e.jpg\",alt:\"南京中山陵\"},\n 16:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_e0b67957ae5b491cbf27fae6a0253154.jpg\",alt:\"武汉长江大桥\"},\n 17:{url:\"https://mdn.alipayobjects.com/asap_serivce/uri/file/as/upload_image_633ab75a06c544f8a0900c6083823c67.jpg\",alt:\"上海陆家嘴天际线\"}\n};\nconst TIPS = [\n\"澶渊之盟（1005）后，北宋每年给辽的岁币只约相当于两个县财政收入，却换来百年和平——\\\"买和平\\\"也有性价比。\",\n\"交子诞生于四川，因为铁钱太重：买一匹布要掏上百斤铁钱。\",\n\"科举制从隋朝（约605年）到1905年废除，前后约1300年，比多数王朝的国祚都长。\",\n\"郑和下西洋的宝船船队早于哥伦布近90年，规模却是后者的几十倍。\",\n\"唐朝长安城面积约为同时期罗马城的7倍，是世界最大的城市。\",\n\"《史记》被鲁迅称为\\\"史家之绝唱，无韵之《离骚》\\\"，记录了从黄帝到汉武帝约3000年历史。\",\n\"秦朝仅存续15年，但秦朝确立的郡县制等制度框架延续了两千多年。\",\n\"\\\"昭君出塞\\\"\\\"文成公主入藏\\\"体现的和亲政策，是古代处理民族关系的重要方式。\",\n\"明清的\\\"海禁\\\"与\\\"闭关\\\"并非绝对禁止贸易，而是严格限制——广州十三行曾是唯一合法口岸。\",\n\"四大发明中，火药的最早记载见于唐代炼丹著作，最初是\\\"求长生\\\"的意外收获。\"\n];\n\n/* ================== 基础常量 ================== */\nconst ERA_TIMES=[\"约前170万—前2070\",\"前2070—前221\",\"前221—220\",\"220—589\",\"581—907\",\"907—1279\",\"1271—1840\",\"1840—1912\",\"1912—1949\",\"1949—至今\"];\nconst PAGES=[\n  {k:\"home\",ico:\"🏠\",t:\"学习首页\"},\n  {k:\"timeline\",ico:\"🧭\",t:\"时光长河\"},\n  {k:\"study\",ico:\"📖\",t:\"朝代研读\"},\n  {k:\"compare\",ico:\"🌍\",t:\"中外对照\"},\n  {k:\"quiz\",ico:\"🎯\",t:\"测验闯关\"},\n  {k:\"cards\",ico:\"🃏\",t:\"闪卡记忆\"},\n  {k:\"notes\",ico:\"📝\",t:\"笔记收藏\"},\n  {k:\"progress\",ico:\"📊\",t:\"学习报告\"}\n];\nconst BADGES=[\n  {ico:\"🌱\",n:\"开卷有益\",d:\"学完 1 个节点\",f:s=>s.learned.length>=1},\n  {ico:\"🧭\",n:\"初识古今\",d:\"学完 5 个节点\",f:s=>s.learned.length>=5},\n  {ico:\"📚\",n:\"通史达人\",d:\"学完 17 个节点\",f:s=>s.learned.length>=17},\n  {ico:\"🎯\",n:\"初试锋芒\",d:\"完成 1 次测验\",f:s=>Object.keys(s.quiz).length>=1},\n  {ico:\"⭐\",n:\"满分王者\",d:\"任一关拿到 3 星\",f:s=>Object.values(s.quiz).some(q=>q.stars>=3)},\n  {ico:\"✍️\",n:\"笔耕不辍\",d:\"写下 3 条笔记\",f:s=>Object.values(s.notes).filter(x=>x&&x.trim()).length>=3},\n  {ico:\"🔖\",n:\"收藏家\",d:\"收藏 5 个节点\",f:s=>s.favs.length>=5},\n  {ico:\"🔥\",n:\"坚持一周\",d:\"累计学习 7 天\",f:s=>Object.keys(s.days).length>=7}\n];\nconst KEY=\"zhts_platform_v1\";\nconst DEFAULT={learned:[],favs:[],notes:{},quiz:{},wrong:[],cards:{},days:{},last:{page:\"home\",eraIdx:0,nodeId:1},mem:false};\nlet S=load();\nfunction load(){\n  try{const o=JSON.parse(localStorage.getItem(KEY)||\"{}\");return Object.assign({},JSON.parse(JSON.stringify(DEFAULT)),o);}catch(e){return JSON.parse(JSON.stringify(DEFAULT));}\n}\nfunction save(){try{localStorage.setItem(KEY,JSON.stringify(S));}catch(e){}}\nfunction today(){const d=new Date();return d.getFullYear()+\"-\"+String(d.getMonth()+1).padStart(2,\"0\")+\"-\"+String(d.getDate()).padStart(2,\"0\");}\nfunction markDay(){S.days[today()]=(S.days[today()]||0)+1;save();}\nfunction esc(s){return String(s==null?\"\":s).replace(/&/g,\"&amp;\").replace(/<\/g,\"&lt;\").replace(/>/g,\"&gt;\").replace(/\"/g,\"&quot;\");}\nfunction cut(s,n){s=String(s||\"\");return s.length>n?s.slice(0,n)+\"…\":s;}\nfunction nodeById(id){return NODES.find(n=>n.id===+id)||NODES[0];}\nfunction eraIdxOf(n){return Math.max(0,ERAS.findIndex(e=>e.name===n.era));}\nfunction nodesOf(i){return NODES.filter(n=>n.era===ERAS[i].name);}\nfunction learned(i){return nodesOf(i).filter(n=>S.learned.includes(n.id)).length;}\nfunction pct(a,b){return b?Math.round(a/b*100):0;}\nfunction stars(){return Object.values(S.quiz).reduce((a,q)=>a+(q.stars||0),0);}\nfunction quizPlays(){return Object.values(S.quiz).reduce((a,q)=>a+(q.plays||0),0);}\nfunction rng(seed){let x=seed*9301+49297;return()=>{x=(x*9301+49297)%233280;return x/233280;};}\nfunction shuffle(arr,r){const a=arr.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}\nfunction toast(msg){const t=document.getElementById(\"toast\");t.textContent=msg;t.classList.add(\"on\");clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove(\"on\"),2800);}\nfunction ring(percent,size,color){\n  const r=size/2-5,c=2*Math.PI*r,off=c*(1-percent/100);\n  return `<svg width=\"${size}\" height=\"${size}\" viewBox=\"0 0 ${size} ${size}\"><circle cx=\"${size/2}\" cy=\"${size/2}\" r=\"${r}\" fill=\"none\" stroke=\"rgba(255,255,255,.28)\" stroke-width=\"7\"/><circle cx=\"${size/2}\" cy=\"${size/2}\" r=\"${r}\" fill=\"none\" stroke=\"${color||\"#fff\"}\" stroke-width=\"7\" stroke-linecap=\"round\" stroke-dasharray=\"${c.toFixed(1)}\" stroke-dashoffset=\"${off.toFixed(1)}\"/><\/svg>`;\n}\n\n/* ================== 全局状态 ================== */\nconst state={page:\"home\",eraIdx:0,nodeId:1,dim:0,tlEra:0,reveal:false,noteOpen:false,assistOpen:false,\n  Q:null,C:{idx:0,flip:false},daily:null,mem:!!S.mem};\nconst DIM_TABS=[\n  {k:\"dimension_politics\",ico:\"🏛\",t:\"政治制度\"},\n  {k:\"dimension_economy\",ico:\"💰\",t:\"经济发展\"},\n  {k:\"dimension_nation\",ico:\"🗺\",t:\"民族与疆域\"},\n  {k:\"dimension_culture\",ico:\"📖\",t:\"思想文化\"},\n  {k:\"dimension_science\",ico:\"🔬\",t:\"科技生活\"},\n  {k:\"dimension_summary\",ico:\"⭐\",t:\"时代总评\"},\n  {k:\"world\",ico:\"🌍\",t:\"世界同期\"}\n];\n\n/* ================== 页面切换 ================== */\nfunction go(page,opts={}){\n  state.page=page;\n  if(opts.eraIdx!=null)state.eraIdx=opts.eraIdx;\n  if(opts.nodeId!=null)state.nodeId=opts.nodeId;\n  if(opts.nodeId!=null){state.dim=0;state.reveal=false;state.noteOpen=false;}\n  document.querySelectorAll(\".view\").forEach(v=>v.classList.remove(\"on\"));\n  document.getElementById(\"v-\"+page).classList.add(\"on\");\n  document.querySelectorAll(\"[data-nav-item]\").forEach(b=>b.classList.toggle(\"on\",b.dataset.navItem===page));\n  document.querySelectorAll(\".side-era\").forEach(b=>b.classList.toggle(\"on\",+b.dataset.era===state.eraIdx));\n  document.getElementById(\"main\").scrollTop=0;\n  closePanels();\n  render();\n  S.last={page,eraIdx:state.eraIdx,nodeId:state.nodeId};save();\n}\nfunction closePanels(){\n  document.getElementById(\"searchPanel\").classList.remove(\"on\");\n  document.getElementById(\"assist\").classList.remove(\"open\");\n  document.getElementById(\"drawerMask\").classList.remove(\"on\");\n  state.assistOpen=false;\n}\nfunction render(){\n  const map={home:renderHome,timeline:renderTimeline,study:renderStudy,compare:renderCompare,quiz:renderQuiz,cards:renderCards,notes:renderNotes,progress:renderProgress};\n  (map[state.page]||renderHome)();\n  renderAssist();renderChrome();\n}\nfunction renderChrome(){\n  const p=pct(S.learned.length,NODES.length);\n  document.getElementById(\"progressTxt\").textContent=S.learned.length+\" / \"+NODES.length;\n  const c=2*Math.PI*9;\n  document.getElementById(\"ringArc\").setAttribute(\"stroke-dasharray\",c.toFixed(1));\n  document.getElementById(\"ringArc\").setAttribute(\"stroke-dashoffset\",(c*(1-p/100)).toFixed(1));\n  document.getElementById(\"memBtn\").classList.toggle(\"on\",state.mem);\n  document.getElementById(\"memBtn\").textContent=state.mem?\"📕\":\"🔖\";\n  document.getElementById(\"memBtn\").title=state.mem?\"记忆模式已开启，点击关闭\":\"开启记忆模式\";\n}\n\n/* ================== 首页 ================== */\nfunction renderHome(){\n  const p=pct(S.learned.length,NODES.length),last=nodeById(S.last.nodeId),li=eraIdxOf(last);\n  const dr=rng(Math.floor(Date.now()/86400000)+77);\n  const q=buildQuestion(dr,NODES[Math.floor(dr()*NODES.length)],Math.floor(dr()*6));\n  state.daily=q;\n  const badges=BADGES.map(b=>`<div class=\"badge ${b.f(S)?\"got\":\"\"}\"><div class=\"bi\">${b.ico}<\/div><b>${b.n}<\/b><small>${b.d}<\/small><\/div>`).join(\"\");\n  document.getElementById(\"v-home\").innerHTML=`\n    <div class=\"hero\">\n      <div class=\"hero-txt\">\n        <h1 class=\"serif\">中华通史 · 五千年通关之旅<\/h1>\n        <p>以时序为骨，从史前文明走到新时代。读史、对照、闯关、记忆，一站学通中国史。<\/p>\n        <div class=\"hero-btns\">\n          <button class=\"btn pri\" data-act=\"continue\">▶ 继续学习 · ${esc(cut(last.node_title,10))}<\/button>\n          <button class=\"btn\" data-act=\"nav\" data-v=\"timeline\">🧭 打开时光长河<\/button>\n          <button class=\"btn\" data-act=\"nav\" data-v=\"quiz\">🎯 去闯关<\/button>\n        <\/div>\n      <\/div>\n      <div class=\"hero-ring\">${ring(p,132,\"#fff\")}<div><b>${p}%<\/b><small>通史进度<br>${S.learned.length} / ${NODES.length} 节点<\/small><\/div><\/div>\n    <\/div>\n    <div class=\"stat-row\">\n      <div class=\"card stat\"><span class=\"ico\">📖<\/span><div><b>${S.learned.length}<\/b><span>已学节点 / 共 ${NODES.length}<\/span><\/div><\/div>\n      <div class=\"card stat\"><span class=\"ico\">⭐<\/span><div><b>${stars()}<\/b><span>测验星星 · ${quizPlays()} 次闯关<\/span><\/div><\/div>\n      <div class=\"card stat\"><span class=\"ico\">🔥<\/span><div><b>${Object.keys(S.days).length}<\/b><span>累计学习天数<\/span><\/div><\/div>\n    <\/div>\n    <div class=\"sec-title\"><h2>🗺 十大时代 · 选一个开始<\/h2><span>点击卡片进入朝代研读<\/span><button class=\"more\" data-act=\"nav\" data-v=\"timeline\">时间轴视图 →<\/button><\/div>\n    <div class=\"era-grid\">${ERAS.map((e,i)=>{\n      const ns=nodesOf(i),dn=learned(i);\n      return `<button class=\"era-tile\" style=\"background:${e.color}\" data-act=\"era\" data-v=\"${i}\">\n        <span class=\"no\">${String(i+1).padStart(2,\"0\")}<\/span><span class=\"ico\">${e.ico}<\/span>\n        <b>${e.name}<\/b><small>${ERA_TIMES[i]}<\/small>\n        <span class=\"bar\"><i style=\"width:${pct(dn,ns.length)}%\"><\/i><\/span><\/button>`;}).join(\"\")}<\/div>\n    <div class=\"two-col\">\n      <div class=\"card pad\">\n        <div class=\"mini-h\">📌 继续上次的学习<\/div>\n        <div style=\"font-size:15px;line-height:1.9;color:var(--ink2)\">上次读到 <b style=\"color:var(--primary-deep)\">${esc(ERAS[li].name)} · ${esc(last.node_title)}<\/b><br><span style=\"font-size:12.5px\">${esc(last.year_label)}<\/span><\/div>\n        <div style=\"margin-top:12px;display:flex;gap:8px;flex-wrap:wrap\"><button class=\"btn pri sm\" data-act=\"continue\">继续研读 →<\/button><button class=\"btn sm\" data-act=\"quizEra\" data-v=\"${li}\">测一测这个时代<\/button><\/div>\n      <\/div>\n      <div class=\"card pad\">\n        <div class=\"mini-h\">⚡ 今日一题 <span class=\"pill\" style=\"margin-left:auto\">每日更新<\/span><\/div>\n        <div class=\"daily-q\" id=\"dailyQ\"><\/div>\n        <div id=\"dailyOpts\"><\/div>\n        <div id=\"dailyFb\" style=\"font-size:12.5px;line-height:1.7;margin-top:8px;color:var(--ink3)\"><\/div>\n      <\/div>\n    <\/div>\n    <div class=\"sec-title\"><h2>🏅 成就徽章<\/h2><span>${BADGES.filter(b=>b.f(S)).length} / ${BADGES.length} 已解锁<\/span><button class=\"more\" data-act=\"nav\" data-v=\"progress\">查看报告 →<\/button><\/div>\n    <div class=\"badges\">${badges}<\/div>\n    <p style=\"text-align:center;color:var(--ink3);font-size:11.5px;margin-top:22px\">史料依据教材通史体系整理 · 学习记录保存在本机 iPad 上 · 支持离线研读<\/p>`;\n  renderDaily();\n}\nfunction renderDaily(){\n  const q=state.daily;if(!q)return;\n  document.getElementById(\"dailyQ\").innerHTML=`<b>${esc(cut(q.q,80))}<\/b>`;\n  document.getElementById(\"dailyOpts\").innerHTML=q.opts.map((o,i)=>`<button class=\"opt-mini\" data-act=\"daily\" data-v=\"${i}\">${\"ABCD\"[i]}. ${esc(o)}<\/button>`).join(\"\");\n  document.getElementById(\"dailyFb\").textContent=\"\";\n}\nfunction answerDaily(i){\n  const q=state.daily;if(!q||q.answered)return;q.answered=true;\n  const box=document.getElementById(\"dailyOpts\");\n  [...box.children].forEach((b,k)=>{b.classList.remove(\"right\",\"wrong\");if(k===q.ans)b.classList.add(\"right\");else if(k===i)b.classList.add(\"wrong\");b.disabled=true;});\n  document.getElementById(\"dailyFb\").innerHTML=(i===q.ans?\"✅ 答对了！\":\"💡 正确答案：\"+\"ABCD\"[q.ans]+\"。\")+\" \"+esc(cut(q.explain,90));\n  markDay();\n}\n\n/* ================== 时间轴 ================== */\nfunction renderTimeline(){\n  const i=state.tlEra,ns=nodesOf(i),n=ns[0]||NODES[0],sc=SCENES[n.id];\n  document.getElementById(\"v-timeline\").innerHTML=`\n    <div class=\"sec-title\" style=\"margin-top:0\"><h2 class=\"serif\">🧭 时光长河<\/h2><span>左右滑动浏览十个时代，点击节点直接进入研读<\/span><\/div>\n    <div class=\"card\" style=\"padding:4px 10px 2px\">\n      <div class=\"tl-wrap hscroll\" id=\"tlWrap\"><div class=\"tl-track\">${ERAS.map((e,k)=>`\n        <div class=\"tl-era ${k===i?\"on\":\"\"}\" data-act=\"tlEra\" data-v=\"${k}\">\n          <div class=\"tl-head\" style=\"background:${e.color}\"><b>${e.ico} ${e.name}<\/b><small>${ERA_TIMES[k]}<\/small><\/div>\n          <div class=\"tl-dot\"><\/div>\n          <div class=\"tl-nodes\">${nodesOf(k).map(x=>`<button class=\"tl-node ${S.learned.includes(x.id)?\"done\":\"\"}\" data-act=\"node\" data-v=\"${x.id}\"><b>${esc(x.node_title)}<\/b><small>${esc(cut(x.year_label,18))}<\/small><\/button>`).join(\"\")}<\/div>\n        <\/div>`).join(\"\")}<\/div><\/div>\n    <\/div>\n    <div class=\"card tl-preview\">\n      <div class=\"scene ${sc?\"\":\"noimg\"}\" style=\"min-height:112px;max-height:140px\">${sc?`<img src=\"${sc.url}\" alt=\"${esc(sc.alt)}\" loading=\"lazy\" style=\"height:112px;min-height:0;max-height:none\" onerror=\"this.parentNode.classList.add('noimg')\"><span class=\"cap\">${esc(sc.alt)}<\/span>`:\"\"}<div class=\"ph\"><span class=\"big\">🏺<\/span>${esc(sc?sc.alt:\"时代场景\")}<\/div><\/div>\n      <div><span class=\"pill\">${ERAS[i].ico} ${ERAS[i].name} · ${ERA_TIMES[i]}<\/span>\n        <h3 class=\"serif\">${esc(n.node_title)}<\/h3>\n        <p>${esc(cut(n.dimension_summary,110))}<\/p>\n        <div style=\"margin-top:12px;display:flex;gap:8px;flex-wrap:wrap\"><button class=\"btn pri sm\" data-act=\"node\" data-v=\"${n.id}\">📖 研读这个时代<\/button><button class=\"btn sm\" data-act=\"quizEra\" data-v=\"${i}\">🎯 闯关测试<\/button><button class=\"btn sm\" data-act=\"tlEra\" data-v=\"${(i+1)%ERAS.length}\">下一个时代 →<\/button><\/div>\n      <\/div>\n    <\/div>\n    <div class=\"sec-title\"><h2>📌 这个时代的关键节点<\/h2><span>共 ${ns.length} 个<\/span><\/div>\n    <div style=\"display:grid;gap:10px\">${ns.map(x=>`<div class=\"card\" style=\"padding:13px 17px;display:flex;gap:12px;align-items:center;flex-wrap:wrap\">\n      <span class=\"pill\">${esc(x.year_label)}<\/span><b style=\"font-size:15px;color:var(--primary-deep)\">${esc(x.node_title)}<\/b>\n      <span style=\"font-size:12.5px;color:var(--ink3);flex:1;min-width:140px\">${esc(cut(x.key_event_tags,40))}<\/span>\n      <button class=\"btn sm\" data-act=\"node\" data-v=\"${x.id}\">进入研读 →<\/button><\/div>`).join(\"\")}<\/div>`;\n}\n\n/* ================== 朝代研读 ================== */\nfunction renderStudy(){\n  const i=state.eraIdx,e=ERAS[i],ns=nodesOf(i);\n  if(!ns.some(x=>x.id===state.nodeId))state.nodeId=ns[0].id;\n  const n=nodeById(state.nodeId),sc=SCENES[n.id],d=DIM_TABS[state.dim];\n  const done=S.learned.includes(n.id),fav=S.favs.includes(n.id),hasNote=!!(S.notes[n.id]||\"\").trim();\n  document.getElementById(\"v-study\").innerHTML=`\n    <div class=\"study-head\">\n      <div class=\"sh-txt\"><h2 class=\"serif\">${e.ico} ${e.name}<\/h2><p>${esc(e.desc)} · <span class=\"yr\" style=\"display:inline-block\">${ERA_TIMES[i]}<\/span><\/p><\/div>\n      <div class=\"study-nav\"><button class=\"btn sm\" data-act=\"eraStep\" data-v=\"-1\" ${i===0?\"disabled\":\"\"}>← 上一时代<\/button><button class=\"btn sm\" data-act=\"eraStep\" data-v=\"1\" ${i===ERAS.length-1?\"disabled\":\"\"}>下一时代 →<\/button><\/div>\n    <\/div>\n    <div style=\"display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:12px\">\n      <span class=\"pill\">本节进度 ${learned(i)} / ${ns.length}<\/span>\n      <div style=\"flex:1;min-width:120px;height:8px;border-radius:8px;background:var(--line2);overflow:hidden\"><i style=\"display:block;height:100%;width:${pct(learned(i),ns.length)}%;background:var(--primary)\"><\/i><\/div>\n      <span style=\"font-size:12px;color:var(--ink3)\">👆 在主内容区左右滑动可切换时代<\/span>\n    <\/div>\n    <div class=\"node-pills\">${ns.map((x,k)=>`<button class=\"node-pill ${x.id===n.id?\"on\":\"\"}\" data-act=\"node\" data-v=\"${x.id}\">${k+1}. ${esc(x.node_title)}${S.learned.includes(x.id)?'<span class=\"tick\">✓<\/span>':\"\"}<\/button>`).join(\"\")}<\/div>\n    <div class=\"study-top\">\n      <div class=\"scene\" id=\"sceneBox\">${sc?`<img src=\"${sc.url}\" alt=\"${esc(sc.alt)}\" loading=\"lazy\" onerror=\"this.parentNode.classList.add('noimg')\"><span class=\"cap\">🖼 ${esc(sc.alt)}<\/span>`:\"\"}<div class=\"ph\"><span class=\"big\">🏺<\/span>${esc(sc?sc.alt:\"时代场景\")}<br><small>图片暂不可用，可继续研读正文<\/small><\/div><\/div>\n      <div class=\"card quick\">\n        <div class=\"mini-h\">⚡ 一分钟速记 <span class=\"pill\" style=\"margin-left:auto\">${esc(n.year_label)}<\/span><\/div>\n        <div class=\"quick-grid\">\n          <div class=\"qi\"><b>🔑 关键词<\/b><span>${esc(n.key_event_tags)}<\/span><\/div>\n          <div class=\"qi\"><b>👤 代表人物<\/b><span>${esc(n.figures||\"—\")}<\/span><\/div>\n          <div class=\"qi\"><b>🌱 前因<\/b><span>${esc(cut(n.cause||\"—\",42))}<\/span><\/div>\n          <div class=\"qi\"><b>➡️ 影响<\/b><span>${esc(cut(n.effect||\"—\",42))}<\/span><\/div>\n        <\/div>\n        <div class=\"study-acts\">\n          <button class=\"btn ${done?\"on\":\"\"} sm\" data-act=\"learn\">${done?\"✅ 已学完\":\"○ 标记已学\"}<\/button>\n          <button class=\"btn ${fav?\"on\":\"\"} sm\" data-act=\"fav\">${fav?\"⭐ 已收藏\":\"⭐ 收藏\"}<\/button>\n          <button class=\"btn sm\" data-act=\"noteOpen\">✍ ${hasNote?\"编辑笔记\":\"写笔记\"}<\/button>\n          <button class=\"btn sm\" data-act=\"quizEra\" data-v=\"${i}\">🎯 去闯关<\/button>\n        <\/div>\n      <\/div>\n    <\/div>\n    <div class=\"card note-editor ${state.noteOpen?\"on\":\"\"}\" id=\"noteEditor\">\n      <div class=\"mini-h\">✍ 我的批注 · ${esc(n.node_title)}<\/div>\n      <textarea id=\"noteText\" placeholder=\"写下你的批注、记忆口诀或疑问…\">${esc(S.notes[n.id]||\"\")}<\/textarea>\n      <div style=\"display:flex;gap:8px;margin-top:10px\"><button class=\"btn pri sm\" data-act=\"noteSave\">保存笔记<\/button><button class=\"btn sm\" data-act=\"noteClose\">收起<\/button><\/div>\n    <\/div>\n    <div class=\"card dim-box\">\n      <div class=\"dim-tabs\">${DIM_TABS.map((t,k)=>`<button class=\"dim-tab ${k===state.dim?\"on\":\"\"}\" data-act=\"dim\" data-v=\"${k}\">${t.ico} ${t.t}<\/button>`).join(\"\")}<\/div>\n      <div class=\"mem-cover ${state.mem&&!state.reveal?\"locked\":\"\"}\" id=\"memCover\" data-act=\"reveal\">\n        <div class=\"dim-body\"><h4>${d.ico} ${d.t}${d.k===\"dimension_summary\"?' <span class=\"pill\">必读<\/span>':\"\"}<\/h4><p>${esc(n[d.k])}<\/p>\n          <div class=\"src\">📎 史料线索：${esc(n.source_note||\"依据通史教材体系整理\")}　|　📅 ${esc(n.year_label)}　|　${n.is_anchor_point?\"★ 一级关键转折点\":\"分段节点\"}${state.mem?\"　|　🔖 记忆模式已开启\":\"\"}<\/div>\n        <\/div>\n      <\/div>\n    <\/div>\n    <div class=\"study-foot\">\n      <button class=\"btn sm\" data-act=\"nodeStep\" data-v=\"-1\" ${ns.indexOf(n)===0?\"disabled\":\"\"}>← 上一节点<\/button>\n      <button class=\"btn sm\" data-act=\"nodeStep\" data-v=\"1\" ${ns.indexOf(n)===ns.length-1?\"disabled\":\"\"}>下一节点 →<\/button>\n      <span class=\"sp\"><\/span>\n      <button class=\"btn pri\" data-act=\"learnNext\">${done?\"✅ 已学完，继续闯关 →\":\"学完了 · 标记并闯关 →\"}<\/button>\n    <\/div>`;\n  const box=document.getElementById(\"sceneBox\");\n  if(box&&!box.querySelector(\"img\"))box.classList.add(\"noimg\");\n}\nfunction renderAssist(){\n  const n=nodeById(state.nodeId),i=eraIdxOf(n),got=BADGES.filter(b=>b.f(S));\n  document.getElementById(\"assist\").innerHTML=`\n    <div class=\"as-title\">学习助手 · LEARNING MATE<\/div>\n    <div class=\"card as-card\">\n      <div class=\"as-ring\">${ring(pct(S.learned.length,NODES.length),66,\"#2563eb\").replace('stroke=\"rgba(255,255,255,.28)\"','stroke=\"#dbe7f7\"')}\n        <div><b>${S.learned.length} / ${NODES.length}<\/b><small>已学节点 · 通史进度 ${pct(S.learned.length,NODES.length)}%<\/small><\/div><\/div>\n    <\/div>\n    <div class=\"card as-card\">\n      <div class=\"mini-h\">📌 当前节点<\/div>\n      <div style=\"font-size:14px;color:var(--primary-deep);font-weight:700;margin-bottom:8px\">${esc(n.node_title)}<\/div>\n      <div class=\"as-kv\"><b>时代<\/b><span>${esc(n.era)} · ${ERA_TIMES[i]}<\/span><\/div>\n      <div class=\"as-kv\"><b>关键词<\/b><span>${esc(cut(n.key_event_tags,40))}<\/span><\/div>\n      <div class=\"as-kv\"><b>人物<\/b><span>${esc(cut(n.figures||\"—\",34))}<\/span><\/div>\n      <div class=\"as-kv\"><b>前因<\/b><span>${esc(cut(n.cause||\"—\",34))}<\/span><\/div>\n      <div class=\"as-kv\"><b>影响<\/b><span>${esc(cut(n.effect||\"—\",34))}<\/span><\/div>\n      <button class=\"btn sm\" style=\"width:100%;margin-top:10px\" data-act=\"node\" data-v=\"${n.id}\">📖 回到研读<\/button>\n    <\/div>\n    <div class=\"card as-card\">\n      <div class=\"mini-h\">💡 历史小贴士 <button class=\"btn sm\" style=\"margin-left:auto\" data-act=\"tip\">换一条<\/button><\/div>\n      <div class=\"as-tip\" id=\"asTip\">${esc(TIPS[Math.floor(Math.random()*TIPS.length)])}<\/div>\n    <\/div>\n    <div class=\"card as-card\">\n      <div class=\"mini-h\">🏅 我的徽章 ${got.length}/${BADGES.length}<\/div>\n      <div class=\"as-badges\">${BADGES.map(b=>`<span class=\"${b.f(S)?\"on\":\"\"}\" title=\"${b.n}：${b.d}\">${b.ico}<\/span>`).join(\"\")}<\/div>\n    <\/div>\n    <p style=\"font-size:11px;color:var(--ink3);line-height:1.8;padding:0 4px\">💡 iPad 小贴士：横屏阅读更舒展；在研读页左右滑动可切换时代；点击「🔖」开启记忆模式自测。<\/p>`;\n}\n\n/* ================== 中外对照 ================== */\nfunction renderCompare(){\n  const i=state.eraIdx,e=ERAS[i],ns=nodesOf(i);\n  document.getElementById(\"v-compare\").innerHTML=`\n    <div class=\"study-head\"><div class=\"sh-txt\"><h2 class=\"serif\">🌍 中外对照 · ${e.name}<\/h2><p>🇨🇳 中国 与 🌍 世界同期重大事件对照 · ${ERA_TIMES[i]}<\/p><\/div>\n      <div class=\"study-nav\"><button class=\"btn sm\" data-act=\"eraStep\" data-v=\"-1\" ${i===0?\"disabled\":\"\"}>← 上一时代<\/button><button class=\"btn sm\" data-act=\"eraStep\" data-v=\"1\" ${i===ERAS.length-1?\"disabled\":\"\"}>下一时代 →<\/button><\/div><\/div>\n    <div class=\"node-pills\">${ERAS.map((x,k)=>`<button class=\"node-pill ${k===i?\"on\":\"\"}\" data-act=\"cmpEra\" data-v=\"${k}\">${x.ico} ${x.name}<\/button>`).join(\"\")}<\/div>\n    ${ns.map(n=>`<div class=\"card cmp-card\"><h3>${esc(n.year_label)} · ${esc(n.node_title)} ${n.is_anchor_point?'<span class=\"pill\">★ 转折点<\/span>':\"\"}<small>${esc(n.era)}<\/small><\/h3>\n      <div class=\"cmp-cols\"><div class=\"cmp-col\"><b>🇨🇳 中国 · 时代总评<\/b>${esc(n.dimension_summary)}<\/div>\n      <div class=\"cmp-col world\"><b>🌍 世界同期<\/b>${esc(n.world)}<\/div><\/div>\n      <div style=\"margin-top:12px;display:flex;gap:8px;flex-wrap:wrap\"><span class=\"pill\">🔑 ${esc(cut(n.key_event_tags,44))}<\/span><button class=\"btn sm\" data-act=\"node\" data-v=\"${n.id}\">📖 研读详情 →<\/button><\/div><\/div>`).join(\"\")}`;\n}\n\n/* ================== 测验题库 ================== */\nfunction pickOther(pool,exclude,n,r){\n  return shuffle(pool.filter(x=>!exclude.includes(x)),r).slice(0,n);\n}\nfunction buildQuestion(r,n,type){\n  const eraNames=ERAS.map(e=>e.name),titles=NODES.map(x=>x.node_title);\n  const tag=String(n.key_event_tags||\"\").split(\"｜\")[0].split(\"|\")[0].trim()||n.node_title;\n  const figure=String(n.figures||\"\").split(/[·、,，]/)[0].trim()||\"这一时期\";\n  const sum=cut(n.dimension_summary,52),world=cut(n.world,52);\n  let q,right,wrongPool,explain,tagLabel=\"\";\n  if(type===0){q=`「${n.node_title}」属于哪一个历史时期？`;right=n.era;wrongPool=eraNames;explain=`${n.node_title} 属于${n.era}（${ERA_TIMES[eraIdxOf(n)]}）。${cut(n.dimension_summary,70)}`;tagLabel=\"时代归属\";}\n  else if(type===1){q=`${n.year_label} 所对应的历史节点是？`;right=n.node_title;wrongPool=titles;explain=`${n.node_title}：${n.year_label}。${cut(n.dimension_summary,70)}`;tagLabel=\"年代辨识\";}\n  else if(type===2){q=`「${tag}」等关键词，最可能与哪一历史节点相关？`;right=n.node_title;wrongPool=titles;explain=`${n.node_title} 的关键词为「${n.key_event_tags}」。${cut(n.dimension_summary,60)}`;tagLabel=\"关键词\";}\n  else if(type===3){q=`${figure} 等人物主要活跃于哪个历史时期？`;right=n.era;wrongPool=eraNames;explain=`${n.node_title}（${n.era}）的代表人物有 ${n.figures}。`;tagLabel=\"历史人物\";}\n  else if(type===4){q=`下列关于「${n.node_title}」的时代总评，正确的是？`;right=sum;wrongPool=NODES.map(x=>cut(x.dimension_summary,52));explain=`${n.node_title}：${cut(n.dimension_summary,90)}`;tagLabel=\"史料理解\";}\n  else{q=`与「${n.node_title}」大体同时期，世界上发生了什么？`;right=world;wrongPool=NODES.map(x=>cut(x.world,52));explain=`世界同期：${cut(n.world,90)}`;tagLabel=\"中外对照\";}\n  const opts=shuffle([right,...pickOther(wrongPool,[right],3,r)],r);\n  return {q,opts,ans:opts.indexOf(right),explain,tag:tagLabel,nodeId:n.id};\n}\nfunction buildSet(eraIdx,count){\n  const r=rng(eraIdx===\"all\"?20261110:1000+eraIdx*137);\n  const pool=eraIdx===\"all\"?NODES.slice():nodesOf(eraIdx);\n  const src=pool.length?pool:NODES;\n  const list=[];\n  for(let k=0;k<count;k++){\n    const n=src[(k*3+Math.floor(r()*src.length))%src.length];\n    list.push(buildQuestion(r,n,k%6));\n  }\n  return list;\n}\nfunction levelKey(k){return k===\"all\"?\"all\":\"e\"+k;}\n\n/* ================== 测验页 ================== */\nfunction renderQuiz(){\n  const box=document.getElementById(\"v-quiz\");\n  if(state.Q&&state.Q.active)return renderQuizRun();\n  if(state.Q&&state.Q.finished)return renderQuizEnd();\n  box.innerHTML=`\n    <div class=\"sec-title\" style=\"margin-top:0\"><h2 class=\"serif\">🎯 测验闯关<\/h2><span>每关 5 题，题目由通史史料自动生成，答错自动进错题本<\/span><\/div>\n    <div class=\"lv-grid\">${ERAS.map((e,i)=>{\n      const q=S.quiz[levelKey(i)],ns=nodesOf(i);\n      return `<button class=\"lv ${q?\"done\":\"\"}\" style=\"background:${e.color}\" data-act=\"quizEra\" data-v=\"${i}\">\n        <span class=\"n\">第 ${String(i+1).padStart(2,\"0\")} 关 · ${ns.length} 个节点<\/span><b>${e.ico} ${e.name}<\/b>\n        <span class=\"stars\">${q?\"★\".repeat(q.stars)+\"☆\".repeat(3-q.stars):\"☆☆☆\"}<\/span>\n        <span class=\"best\">${q?\"最佳 \"+q.best+\"/5 · 已闯 \"+(q.plays||1)+\" 次\":\"尚未挑战\"}<\/span><\/button>`;}).join(\"\")}\n      <button class=\"lv\" style=\"background:linear-gradient(135deg,#dbeafe,#bfdbfe);grid-column:span 2\" data-act=\"quizEra\" data-v=\"all\">\n        <span class=\"n\">终极挑战 · 全部 17 节点<\/span><b>🏆 通史综合挑战<\/b>\n        <span class=\"stars\">${S.quiz.all?\"★\".repeat(S.quiz.all.stars)+\"☆\".repeat(3-S.quiz.all.stars):\"☆☆☆\"}<\/span>\n        <span class=\"best\">${S.quiz.all?\"最佳 \"+S.quiz.all.best+\"/10\":\"10 题 · 跨时代随机\"}<\/span><\/button>\n    <\/div>\n    <div class=\"sec-title\"><h2>📕 错题本<\/h2><span>${S.wrong.length} 条<\/span>${S.wrong.length?'<button class=\"more\" data-act=\"clearWrong\">清空错题<\/button>':\"\"}<\/div>\n    ${S.wrong.length?`<div class=\"card pad\">${S.wrong.slice(-8).reverse().map(w=>`<div style=\"padding:9px 0;border-bottom:1px dashed var(--line2);font-size:13.5px;line-height:1.7\"><b style=\"color:var(--primary-deep)\">${esc(w.q)}<\/b><br><span style=\"color:var(--ink2)\">正确：${esc(w.right)}<\/span> <button class=\"btn sm\" style=\"margin-left:8px\" data-act=\"node\" data-v=\"${w.nodeId}\">去复习 →<\/button><\/div>`).join(\"\")}<\/div>`:`<div class=\"card empty\">还没有错题，去闯一关吧 🎯<\/div>`}`;\n}\nfunction startQuiz(k){\n  const count=k===\"all\"?10:5;\n  state.Q={key:k,list:buildSet(k,count),idx:0,score:0,active:true,finished:false,picked:null,wrong:0};\n  renderQuizRun();\n}\nfunction renderQuizRun(){\n  const Q=state.Q,q=Q.list[Q.idx],total=Q.list.length;\n  document.getElementById(\"v-quiz\").innerHTML=`\n    <div class=\"q-wrap\">\n      <div class=\"q-head\"><span>第 ${Q.idx+1} / ${total} 题<\/span><div class=\"prog\"><i style=\"width:${pct(Q.idx,total)}%\"><\/i><\/div><span>✅ ${Q.score} 分<\/span><button class=\"btn sm\" data-act=\"quizExit\">退出<\/button><\/div>\n      <div class=\"card q-card\">\n        <div class=\"tag\">${esc(q.tag)} · ${esc(nodeById(q.nodeId).era)}<\/div>\n        <h3>${esc(q.q)}<\/h3>\n        <div class=\"q-opts\" id=\"qOpts\">${q.opts.map((o,i)=>`<button class=\"q-opt\" data-act=\"answer\" data-v=\"${i}\"><span class=\"k\">${\"ABCD\"[i]}<\/span><span>${esc(o)}<\/span><\/button>`).join(\"\")}<\/div>\n        <div id=\"qExplain\"><\/div>\n        <div class=\"q-foot\"><button class=\"btn pri\" id=\"qNext\" data-act=\"qNext\" style=\"display:none\">${Q.idx===total-1?\"查看结算 →\":\"下一题 →\"}<\/button><\/div>\n      <\/div>\n      <p style=\"text-align:center;color:var(--ink3);font-size:12px;margin-top:14px\">大按钮适合 iPad 触控 · 答完立刻显示解析<\/p>\n    <\/div>`;\n}\nfunction answerQuiz(i){\n  const Q=state.Q;if(!Q||Q.picked!=null)return;\n  const q=Q.list[Q.idx];Q.picked=i;\n  const opts=document.querySelectorAll(\"#qOpts .q-opt\");\n  opts.forEach((b,k)=>{b.classList.add(\"disabled\");if(k===q.ans)b.classList.add(\"right\");else if(k===i)b.classList.add(\"wrong\");});\n  if(i===q.ans)Q.score++;else{Q.wrong++;S.wrong.push({q:cut(q.q,70),right:cut(q.opts[q.ans],70),nodeId:q.nodeId});save();}\n  document.getElementById(\"qExplain\").innerHTML=`<div class=\"q-explain\"><b>${i===q.ans?\"✅ 答对了！\":\"❌ 再记一下：\"}<\/b> ${esc(q.explain)}<\/div>`;\n  document.getElementById(\"qNext\").style.display=\"inline-flex\";\n}\nfunction nextQuestion(){\n  const Q=state.Q;Q.idx++;Q.picked=null;\n  if(Q.idx>=Q.list.length)return finishQuiz();\n  renderQuizRun();\n}\nfunction finishQuiz(){\n  const Q=state.Q,total=Q.list.length,ratio=Q.score/total;\n  const st=ratio>=.9?3:ratio>=.7?2:ratio>=.5?1:0;\n  const k=levelKey(Q.key),old=S.quiz[k]||{best:0,stars:0,plays:0};\n  S.quiz[k]={best:Math.max(old.best,Q.score),stars:Math.max(old.stars,st),plays:(old.plays||0)+1};\n  Q.active=false;Q.finished=true;Q.stars=st;Q.total=total;\n  save();markDay();renderQuizEnd();renderChrome();renderAssist();\n}\nfunction renderQuizEnd(){\n  const Q=state.Q;\n  document.getElementById(\"v-quiz\").innerHTML=`\n    <div class=\"card result\"><div class=\"big\">${Q.stars===3?\"🏆\":Q.stars>=1?\"🎉\":\"📖\"}<\/div>\n      <h3>${Q.stars===3?\"太棒了，满分通关！\":Q.stars>=1?\"闯关成功！\":\"再读一遍就更稳了\"}<\/h3>\n      <div class=\"stars\">${\"★\".repeat(Q.stars)+\"☆\".repeat(3-Q.stars)}<\/div>\n      <p>答对 <b style=\"color:var(--primary-deep);font-size:18px\">${Q.score} / ${Q.total}<\/b> 题　·　错题 ${Q.wrong} 道已收进错题本<br>${Q.key===\"all\"?\"通史综合挑战\":ERAS[+Q.key].name+\" · \"+ERA_TIMES[+Q.key]}<\/p>\n      <div class=\"btns\"><button class=\"btn pri\" data-act=\"quizEra\" data-v=\"${Q.key}\">🔁 再挑战一次<\/button><button class=\"btn\" data-act=\"nav\" data-v=\"quiz\">🗂 返回关卡<\/button><button class=\"btn\" data-act=\"nav\" data-v=\"study\">📖 回去研读<\/button><\/div>\n    <\/div>`;\n}\n\n/* ================== 闪卡 ================== */\nfunction renderCards(){\n  const order=NODES.slice().sort((a,b)=>(S.cards[a.id]||0)-(S.cards[b.id]||0));\n  const n=order[state.C.idx%order.length],mastered=NODES.filter(x=>(S.cards[x.id]||0)>=2).length;\n  document.getElementById(\"v-cards\").innerHTML=`\n    <div class=\"sec-title\" style=\"margin-top:0\"><h2 class=\"serif\">🃏 闪卡记忆<\/h2><span>点卡片翻面自测 · 已熟练掌握 ${mastered} / ${NODES.length}<\/span><\/div>\n    <div class=\"flip-stage\">\n      <div class=\"flip ${state.C.flip?\"on\":\"\"}\" data-act=\"flip\" id=\"flipCard\"><div class=\"flip-in\">\n        <div class=\"face front\"><div class=\"lbl\">CARD ${state.C.idx%order.length+1} / ${order.length}<\/div><h3 class=\"serif\">${esc(n.node_title)}<\/h3><p>它属于哪个时代？起止年代是什么？<br>试着先自己说出来，再翻面对答案。<\/p><div class=\"hint\">👆 点击卡片翻面<\/div><\/div>\n        <div class=\"face back\"><div class=\"lbl\">${esc(n.era)}<\/div><h3>${esc(n.year_label)}<\/h3><p>${esc(cut(n.dimension_summary,120))}<\/p>\n          <div class=\"tags\">${String(n.key_event_tags||\"\").split(/[｜|]/).slice(0,4).map(t=>`<span>${esc(t)}<\/span>`).join(\"\")}<span>👤 ${esc(cut(n.figures||\"—\",30))}<\/span><\/div><\/div>\n      <\/div><\/div>\n      <div class=\"flip-ctrl\">\n        <button class=\"btn sm\" data-act=\"cardStep\" data-v=\"-1\">← 上一张<\/button>\n        <button class=\"btn\" data-act=\"flip\">🔄 翻面<\/button>\n        <button class=\"btn sm\" data-act=\"cardStep\" data-v=\"1\">下一张 →<\/button>\n        <button class=\"btn pri sm\" data-act=\"cardKnow\" data-v=\"1\">✅ 记住了<\/button>\n        <button class=\"btn sm\" data-act=\"cardKnow\" data-v=\"0\">🔁 再练<\/button>\n        <button class=\"btn sm\" data-act=\"node\" data-v=\"${n.id}\">📖 看原文<\/button>\n      <\/div>\n      <p style=\"text-align:center;color:var(--ink3);font-size:12px;margin-top:14px\">不熟悉的卡片会优先出现 · 连续两次「记住了」即算掌握<\/p>\n    <\/div>`;\n}\n\n/* ================== 笔记收藏 ================== */\nfunction renderNotes(){\n  const ks=Object.keys(S.notes).filter(k=>(S.notes[k]||\"\").trim());\n  document.getElementById(\"v-notes\").innerHTML=`\n    <div class=\"sec-title\" style=\"margin-top:0\"><h2 class=\"serif\">📝 我的笔记与收藏<\/h2><span>共 ${ks.length} 条笔记 · ${S.favs.length} 个收藏，全部保存在本机<\/span><\/div>\n    <div class=\"two-col\" style=\"margin-top:0\">\n      <div><div class=\"mini-h\">✍ 批注 (${ks.length})<\/div>\n        ${ks.length?ks.map(k=>{const n=NODES.find(x=>x.id==k);return `<div class=\"card note-item\"><h4>${esc(n?n.node_title:\"节点\"+k)} <span class=\"pill\">${esc(n?n.era:\"\")}<\/span><\/h4><p>${esc(S.notes[k])}<\/p><div class=\"row\"><button class=\"btn sm\" data-act=\"node\" data-v=\"${k}\">📖 回到研读<\/button><button class=\"btn sm\" data-act=\"noteDel\" data-v=\"${k}\">🗑 删除<\/button><\/div><\/div>`;}).join(\"\"):`<div class=\"card empty\">还没有笔记。<br>在「朝代研读」里点「✍ 写笔记」就能记下你的口诀和疑问。<\/div>`}<\/div>\n      <div><div class=\"mini-h\">⭐ 收藏节点 (${S.favs.length})<\/div>\n        ${S.favs.length?S.favs.map(k=>{const n=NODES.find(x=>x.id==k);return n?`<div class=\"card note-item\" style=\"display:flex;align-items:center;gap:10px;flex-wrap:wrap\"><h4 style=\"flex:1\">${esc(n.node_title)}<\/h4><span class=\"pill\">${esc(n.era)}<\/span><button class=\"btn sm\" data-act=\"node\" data-v=\"${k}\">进入 →<\/button><button class=\"btn sm\" data-act=\"fav\" data-v=\"${k}\">取消<\/button><\/div>`:\"\";}).join(\"\"):`<div class=\"card empty\">还没有收藏。<br>遇到重点节点，点「⭐ 收藏」就能在这里快速找到。<\/div>`}<\/div>\n    <\/div>`;\n}\n\n/* ================== 学习报告 ================== */\nfunction renderProgress(){\n  const days=[];for(let k=6;k>=0;k--){const d=new Date();d.setDate(d.getDate()-k);days.push(d.getFullYear()+\"-\"+String(d.getMonth()+1).padStart(2,\"0\")+\"-\"+String(d.getDate()).padStart(2,\"0\"));}\n  document.getElementById(\"v-progress\").innerHTML=`\n    <div class=\"sec-title\" style=\"margin-top:0\"><h2 class=\"serif\">📊 学习报告<\/h2><span>数据保存在本机 iPad，无需联网<\/span><\/div>\n    <div class=\"stat-row\">\n      <div class=\"card stat\"><span class=\"ico\">📖<\/span><div><b>${S.learned.length}/${NODES.length}<\/b><span>已学节点<\/span><\/div><\/div>\n      <div class=\"card stat\"><span class=\"ico\">⭐<\/span><div><b>${stars()}<\/b><span>累计星星<\/span><\/div><\/div>\n      <div class=\"card stat\"><span class=\"ico\">🎯<\/span><div><b>${quizPlays()}<\/b><span>闯关次数<\/span><\/div><\/div>\n    <\/div>\n    <div class=\"report-grid\" style=\"margin-top:14px\">\n      <div class=\"card pad\"><div class=\"mini-h\">🗺 各时代掌握度<\/div>\n        ${ERAS.map((e,i)=>{const ns=nodesOf(i),v=pct(learned(i),ns.length);return `<div class=\"bar-row\"><span class=\"nm\">${e.ico} ${e.name}<\/span><span class=\"bar\"><i style=\"width:${v}%\"><\/i><\/span><span class=\"pc\">${learned(i)}/${ns.length}<\/span><\/div>`;}).join(\"\")}\n      <\/div>\n      <div>\n        <div class=\"card pad\"><div class=\"mini-h\">🎯 闯关成绩<\/div>\n          ${ERAS.map((e,i)=>{const q=S.quiz[levelKey(i)];return `<div class=\"bar-row\"><span class=\"nm\">${e.name}<\/span><span style=\"flex:1;font-size:13px;color:${q?\"var(--gold)\":\"var(--ink3)\"}\">${q?\"★\".repeat(q.stars)+\"☆\".repeat(3-q.stars)+\"　最佳 \"+q.best+\"/5\":\"未挑战\"}<\/span><\/div>`;}).join(\"\")}\n          <div class=\"bar-row\"><span class=\"nm\">综合挑战<\/span><span style=\"flex:1;font-size:13px;color:${S.quiz.all?\"var(--gold)\":\"var(--ink3)\"}\">${S.quiz.all?\"最佳 \"+S.quiz.all.best+\"/10\":\"未挑战\"}<\/span><\/div>\n        <\/div>\n        <div class=\"card pad\" style=\"margin-top:14px\"><div class=\"mini-h\">🔥 最近 7 天<\/div>\n          <div class=\"day-strip\">${days.map(d=>`<i class=\"${S.days[d]?\"on\":\"\"}\" title=\"${d}\">${d.slice(5).replace(\"-\",\"/\")}<\/i>`).join(\"\")}<\/div>\n          <p style=\"font-size:12px;color:var(--ink3);margin-top:10px\">累计学习 ${Object.keys(S.days).length} 天 · ${Object.values(S.days).reduce((a,b)=>a+b,0)} 次学习动作<\/p>\n        <\/div>\n      <\/div>\n    <\/div>\n    <div class=\"sec-title\"><h2>🏅 成就徽章<\/h2><span>${BADGES.filter(b=>b.f(S)).length} / ${BADGES.length} 已解锁<\/span><\/div>\n    <div class=\"badges\">${BADGES.map(b=>`<div class=\"badge ${b.f(S)?\"got\":\"\"}\"><div class=\"bi\">${b.ico}<\/div><b>${b.n}<\/b><small>${b.d}<\/small><\/div>`).join(\"\")}<\/div>\n    <div class=\"card pad\" style=\"margin-top:16px;display:flex;gap:10px;align-items:center;flex-wrap:wrap\"><span style=\"font-size:13px;color:var(--ink2);flex:1;min-width:180px\">学习记录只保存在这台 iPad 上。若换了设备，可以重新开始，也可以导出备份。<\/span><button class=\"btn sm\" data-act=\"export\">📤 导出学习记录<\/button><button class=\"btn sm\" data-act=\"reset\">♻️ 清空记录<\/button><\/div>`;\n}\n\n/* ================== 搜索 ================== */\nfunction doSearch(q){\n  const panel=document.getElementById(\"searchPanel\");\n  q=q.trim().toLowerCase();\n  if(!q){panel.classList.remove(\"on\");return;}\n  const list=NODES.filter(n=>[n.node_title,n.year_label,n.era,n.key_event_tags,n.figures,n.dimension_politics,n.dimension_economy,n.dimension_nation,n.dimension_culture,n.dimension_science,n.dimension_summary,n.world].join(\" \").toLowerCase().includes(q));\n  panel.innerHTML=list.length?list.slice(0,12).map(n=>`<button data-act=\"node\" data-v=\"${n.id}\"><b>${esc(n.node_title)}<\/b> · ${esc(n.year_label)}<small>${esc(n.era)}　${esc(cut(n.key_event_tags,42))}<\/small><\/button>`).join(\"\"):`<div class=\"none\">未找到匹配节点，试试「都江堰」「科举」「安史之乱」<\/div>`;\n  panel.classList.add(\"on\");\n}\n\n/* ================== 事件总线 ================== */\ndocument.addEventListener(\"click\",e=>{\n  const el=e.target.closest(\"[data-act]\");\n  if(!el){if(!e.target.closest(\".search-wrap\"))document.getElementById(\"searchPanel\").classList.remove(\"on\");return;}\n  const a=el.dataset.act,v=el.dataset.v;\n  switch(a){\n    case \"nav\":go(v);break;\n    case \"era\":go(\"study\",{eraIdx:+v,nodeId:nodesOf(+v)[0].id});break;\n    case \"node\":{const n=nodeById(+v);go(\"study\",{eraIdx:eraIdxOf(n),nodeId:n.id});break;}\n    case \"eraStep\":{const t=state.eraIdx+ +v;if(t>=0&&t<ERAS.length)go(state.page,{eraIdx:t,nodeId:nodesOf(t)[0].id});break;}\n    case \"nodeStep\":{const ns=nodesOf(state.eraIdx),k=ns.findIndex(x=>x.id===state.nodeId)+ +v;if(k>=0&&k<ns.length){state.nodeId=ns[k].id;state.dim=0;state.reveal=false;state.noteOpen=false;render();}break;}\n    case \"cmpEra\":go(\"compare\",{eraIdx:+v});break;\n    case \"tlEra\":state.tlEra=+v;renderTimeline();break;\n    case \"dim\":state.dim=+v;state.reveal=false;renderStudy();break;\n    case \"reveal\":if(state.mem&&!state.reveal){state.reveal=true;renderStudy();}break;\n    case \"mem\":state.mem=!state.mem;S.mem=state.mem;save();state.reveal=false;renderChrome();if(state.page===\"study\")renderStudy();toast(state.mem?\"🔖 记忆模式开启：研读页正文已遮盖，点击卡片揭开答案\":\"记忆模式已关闭\");break;\n    case \"tip\":{const t=TIPS[Math.floor(Math.random()*TIPS.length)],x=document.getElementById(\"asTip\");if(x)x.textContent=t;toast(\"💡 \"+t);break;}\n    case \"assist\":state.assistOpen=!state.assistOpen;document.getElementById(\"assist\").classList.toggle(\"open\",state.assistOpen);document.getElementById(\"drawerMask\").classList.toggle(\"on\",state.assistOpen);break;\n    case \"closeAssist\":document.getElementById(\"assist\").classList.remove(\"open\");document.getElementById(\"drawerMask\").classList.remove(\"on\");state.assistOpen=false;break;\n    case \"learn\":{const id=state.nodeId,k=S.learned.indexOf(id);if(k<0){S.learned.push(id);toast(\"✅ 已标记学完：「\"+nodeById(id).node_title+\"」\");}else{S.learned.splice(k,1);toast(\"已取消已学标记\");}save();markDay();render();break;}\n    case \"fav\":{const id=v!=null?+v:state.nodeId,k=S.favs.indexOf(id);if(k<0){S.favs.push(id);toast(\"⭐ 已收藏\");}else{S.favs.splice(k,1);toast(\"已取消收藏\");}save();render();break;}\n    case \"noteOpen\":state.noteOpen=!state.noteOpen;renderStudy();if(state.noteOpen)setTimeout(()=>document.getElementById(\"noteText\")&&document.getElementById(\"noteText\").focus(),50);break;\n    case \"noteClose\":state.noteOpen=false;renderStudy();break;\n    case \"noteSave\":{const t=document.getElementById(\"noteText\").value;if(t.trim())S.notes[state.nodeId]=t;else delete S.notes[state.nodeId];save();state.noteOpen=false;render();toast(\"✍ 笔记已保存，可在「笔记收藏」查看\");break;}\n    case \"noteDel\":delete S.notes[v];save();renderNotes();toast(\"笔记已删除\");break;\n    case \"continue\":{const n=nodeById(S.last.nodeId);go(\"study\",{eraIdx:eraIdxOf(n),nodeId:n.id});break;}\n    case \"learnNext\":{if(!S.learned.includes(state.nodeId)){S.learned.push(state.nodeId);save();markDay();toast(\"✅ 已标记学完，去闯关吧！\");}startQuiz(state.eraIdx);go(\"quiz\");break;}\n    case \"daily\":answerDaily(+v);break;\n    case \"quizEra\":startQuiz(v===\"all\"?\"all\":+v);go(\"quiz\");break;\n    case \"answer\":answerQuiz(+v);break;\n    case \"qNext\":nextQuestion();break;\n    case \"quizExit\":state.Q=null;renderQuiz();break;\n    case \"clearWrong\":S.wrong=[];save();renderQuiz();toast(\"错题本已清空\");break;\n    case \"flip\":state.C.flip=!state.C.flip;renderCards();break;\n    case \"cardStep\":state.C.idx=(state.C.idx+ +v+NODES.length)%NODES.length;state.C.flip=false;renderCards();break;\n    case \"cardKnow\":{const order=NODES.slice().sort((a,b)=>(S.cards[a.id]||0)-(S.cards[b.id]||0)),n=order[state.C.idx%order.length];S.cards[n.id]=v===\"1\"?Math.min(2,(S.cards[n.id]||0)+1):0;save();state.C.idx=(state.C.idx+1)%NODES.length;state.C.flip=false;renderCards();toast(v===\"1\"?\"✅ 记住了，这张卡会少出现\":\"🔁 已放回练习队列\");break;}\n    case \"export\":{const blob=new Blob([JSON.stringify(S,null,2)],{type:\"application/json\"}),u=URL.createObjectURL(blob),a=document.createElement(\"a\");a.href=u;a.download=\"中华通史-学习记录-\"+today()+\".json\";a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast(\"学习记录已导出\");break;}\n    case \"reset\":if(confirm(\"⚠️ 确定清空全部学习记录（已学、笔记、收藏、成绩）吗？此操作不可恢复。\")){S=JSON.parse(JSON.stringify(DEFAULT));save();state.Q=null;render();toast(\"已清空全部学习记录\");}break;\n  }\n});\ndocument.getElementById(\"searchInput\").addEventListener(\"input\",e=>doSearch(e.target.value));\ndocument.getElementById(\"searchInput\").addEventListener(\"focus\",e=>{if(e.target.value.trim())doSearch(e.target.value);});\ndocument.addEventListener(\"keydown\",e=>{\n  if(e.key===\"Escape\"){closePanels();return;}\n  if(/input|textarea/i.test(document.activeElement.tagName))return;\n  if(e.key===\"ArrowLeft\"&&[\"study\",\"compare\"].includes(state.page)){const t=state.eraIdx-1;if(t>=0)go(state.page,{eraIdx:t,nodeId:nodesOf(t)[0].id});}\n  if(e.key===\"ArrowRight\"&&[\"study\",\"compare\"].includes(state.page)){const t=state.eraIdx+1;if(t<ERAS.length)go(state.page,{eraIdx:t,nodeId:nodesOf(t)[0].id});}\n});\n/* 触屏左右滑动切换时代（避开可横向滚动区域） */\nlet tx=null,ty=null,tTarget=null;\nconst main=document.getElementById(\"main\");\nmain.addEventListener(\"touchstart\",e=>{tx=e.touches[0].clientX;ty=e.touches[0].clientY;tTarget=e.target;},{passive:true});\nmain.addEventListener(\"touchend\",e=>{\n  if(tx===null)return;\n  const dx=e.changedTouches[0].clientX-tx,dy=e.changedTouches[0].clientY-ty;\n  const skip=tTarget&&tTarget.closest&&tTarget.closest(\".hscroll,.node-pills,.dim-tabs,.tabbar,input,textarea,.flip\");\n  if(!skip&&[\"study\",\"compare\"].includes(state.page)&&Math.abs(dx)>80&&Math.abs(dx)>Math.abs(dy)*1.8){\n    const t=state.eraIdx+(dx<0?1:-1);\n    if(t>=0&&t<ERAS.length){go(state.page,{eraIdx:t,nodeId:nodesOf(t)[0].id});toast((dx<0?\"→ \":\"← \")+ERAS[t].name);}\n  }\n  tx=null;\n},{passive:true});\n\n/* ================== 初始化 ================== */\ndocument.getElementById(\"sideNav\").innerHTML=PAGES.map(p=>`<button class=\"nav-item\" data-nav-item=\"${p.k}\" data-act=\"nav\" data-v=\"${p.k}\" title=\"${p.t}\"><span class=\"ni\">${p.ico}<\/span><span>${p.t}<\/span><\/button>`).join(\"\");\ndocument.getElementById(\"sideEras\").innerHTML=`<div class=\"side-cap\">朝代速查<\/div>`+ERAS.map((e,i)=>`<button class=\"side-era\" data-era=\"${i}\" data-act=\"era\" data-v=\"${i}\"><i style=\"background:${e.color}\"><\/i>${e.name}<\/button>`).join(\"\");\ndocument.getElementById(\"tabbar\").innerHTML=PAGES.map(p=>`<button data-nav-item=\"${p.k}\" data-act=\"nav\" data-v=\"${p.k}\"><span class=\"ni\">${p.ico}<\/span>${p.t.replace(\"学习\",\"\").replace(\"朝代\",\"\").replace(\"记忆\",\"\").replace(\"收藏\",\"\")}<\/button>`).join(\"\");\nmarkDay();\ngo(\"home\");\nsetTimeout(()=>toast(\"欢迎来到中华通史学习平台 · 横屏使用更舒展，左右滑动可切换时代\"),700);\n<\/script>\n<\/body>\n<\/html>\n";
